quests[38681] = { id = 38681, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Stormheim - Treasure 028 - Mountain Cave - ZTO" }
quests[38682] = { id = 38682, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Censer of Torment" }
quests[38683] = { id = 38683, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Looted Bleeding Hollow Sack" }
quests[38684] = { id = 38684, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Weisheit der Blätter", description = "{name}, <mein Freund/meine Freundin>. Ihr müsst vollbringen, was mir versagt blieb. Ihr müsst unseren teuren Malfurion finden.\n\nDer Alptraum verschlingt meinen Geist, und ich höre die Stimmen dieser gequälten Bäume. Aber ich muss an meinem Verstand festhalten, um Euch zu helfen.\n\nBegebt Euch nach Ash'theran und bringt mir verderbte Blütenblätter von denen, die dort gefallen sind.\n\nMit ihrer Hilfe finde ich vielleicht Euren Erzdruiden, solange ich noch bei klarem Verstand bin.", sourceObjective = "Sammelt 5 verderbte Blütenblätter.", progress = "Ahh... die Furcht! Die Panik!\n\nMir fehlt die Kraft, noch viel länger zu kämpfen...", completion = "Die wache Welt entzieht sich meinem Geist Stück für Stück. Aber auch, wenn die Verderbnis meinen Verstand schon fast zunichte gemacht hat, kann ich Malfurion spüren!", sourceObjectiveStatus = "unverified-source-field" }
quests[38685] = { id = 38685, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Nameless King" }
quests[38686] = { id = 38686, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Rune Etched Femur" }
quests[38687] = { id = 38687, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem Ziel so nahe", description = "Er ist ganz in der Nähe, {name}. Ich fühle es.\n\nWir müssen diesen Ort gründlich nach meinem Gatten absuchen. Wenn wir ihn nicht bald finden, könnte es für ihn zu spät sein.\n\nIhr habt während unserer ganzen Suche großen Mut bewiesen. Ich weiß, Ihr werdet mich jetzt nicht im Stich lassen, {name}.\n\nVielen Dank, und beeilt Euch bitte.", sourceObjective = "Sucht in Shala'nir nach Malfurion.", completion = "Das darf nicht sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[38689] = { id = 38689, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämonische Heilung", description = "All diese Jahre in Gefangenschaft haben ihre Spuren hinterlassen.\n\nIm Verlies wimmelt es nur so von Dämonen. Tötet sie und stärkt Euch an ihren Seelen.", sourceObjective = "Nehmt 100 Energie von gefallenen Dämonen in Euch auf.", completion = "Euer Gesicht hat wieder Farbe angenommen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[38690] = { id = 38690, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Illidari erheben sich", description = "Seht! Dort unten. Wir sind zahlenmäßig weit unterlegen.\n\nWenn wir wünschen, diesen Ort lebend zu verlassen, werden wir mehr Verbündete brauchen. Befreit die anderen Illidarigefangenen in den Zellen dieser Kammer.\n\nJetzt kommt es auf jeden Kämpfer an.", sourceObjective = "Befreit 8 gefangene Illidari.", completion = "Wir wussten, die Illidari würden zur Verteidigung dieser Welt gerufen werden. Aus diesem Grund haben wir alles geopfert. Um zu werden wer... WAS wir sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[38691] = { id = 38691, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jarods Mission", description = "Seit Maiev Gul'dan im Verlies der Wächterinnen nachgestürmt ist, haben ihre Schwestern unter den Wächterinnen sie überall gesucht.\n\nDa uns nur wenige Wächterinnen verblieben sind, habe auch ich mich der Suche freiwillig angeschlossen. Ich hoffe, ich finde in der Rabenwehr Hinweise auf ihren Verbleib.\n\nDiese Festung wird gut bewacht. Ich werde Hilfe brauchen, um dort einzudringen. Helft mir, sie zu finden, und ich werde Euch großzügig entlohnen.", sourceObjective = "Sprecht mit Jarod Schattensang beim Mausoleum des Hauses Rabenkrone.", completion = "Was will die Legion von Rabenkrone? Er ist tot und wurde schon vor zehntausend Jahren beerdigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[38692] = { id = 38692, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reaktion auf Aggression", description = "Heute weine ich um die Nachtgeborenen.\n\n<Silgryn weist zur Tür heraus.>\n\nElisande beweist ihre ultimative Geringschätzung für ihr Volk. So viele Leben wurden geopfert!\n\nUnd das alles nur für eine einzige Botschaft, eine Warnung an alle, die sich ihr widersetzen.\n\n{name}, wir müssen darauf reagieren. Wir müssen ihr zeigen, dass sie ihre Leute nicht einfach so abschlachten kann.\n\nSchlagt zurück, {name}.", sourceObjective = "Tötet 12 Soldaten von Elisande am Mondsichelforum, in der Zuflucht des Sternenrufers und in der Sirenenwacht.", completion = "Es musste getan werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[38694] = { id = 38694, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neu formieren", description = "Diese Leute können vielleicht hier durchhalten, aber das gilt nicht für uns.\n\nJeder Moment, den wir hier verbringen, schürt die Gefahr, dass Elisandes Truppen sie angreifen, um sich an uns zu rächen.\n\nWir müssen hier weg und einen Ort finden, wo wir uns neu formieren und erholen können.\n\nFolgt mir. Ich glaube, ich weiß, wie wir hier rauskommen.", sourceObjective = "Entkommt aus der Sirenenwacht.", completion = "Oculeth hat unsere Ankunft erwartet. Umso besser: eine Sorge weniger.", sourceObjectiveStatus = "unverified-source-field" }
quests[38695] = { id = 38695, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Verbindung", description = "Thalyssras Sorgen sind berechtigt!\n\nDas Netzwerk hat auf meine Versuche, die Verbindung mit dem Mondsichelforum wiederherzustellen, nicht reagiert. Ich weiß nicht, was geschehen ist, aber angesichts der Umstände halte ich eine persönliche Untersuchung für angebracht.\n\n{name}, würdet Ihr diese Aufgabe übernehmen? Ich werde Euch so nahe an das Mondsichelforum heranbringen, wie ich kann.", sourceObjective = "Untersucht die Ereignisse am Mondsichelforum.", progress = "Elisande... Wie konntet Ihr nur?", completion = "Jemand muss der Großmagistrix von Vanthirs Rolle bei der Rebellion berichtet haben. Diese unverhältnismäßige Gewalt...\n\nElisande... Wie konntet Ihr nur?", sourceObjectiveStatus = "unverified-source-field" }
quests[38696] = { id = 38696, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Bleeding Hollow Horror" }
quests[38697] = { id = 38697, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schwert der Wahrheit", description = "Die Armee von Lord Rabenkrone erhebt sich aus dem Tod, aber ich glaube, dass Gul'dan sie kontrolliert.\n\nNehmt dies. Das ist Lord Rabenkrones Schwert Fal'shathil. Es war für seine einzigartigen magischen Fähigkeiten weithin bekannt. Wer die spiegelnde Klinge erblickt hatte, konnte die Wahrheit nicht leugnen.\n\nNehmt das Schwert und stoßt es in den Boden. Greift dann die Nachtelfengeister in seinem Lichtschein an. Sobald sie geschwächt sind, werden sie vielleicht wieder zur Vernunft kommen.", sourceObjective = "Stoßt Fal'shathil in den Boden und besiegt dann die Rabenwehrnachtelfen in seinem heiligen Lichtschein.", sourceObjectiveStatus = "unverified-source-field" }
quests[38700] = { id = 38700, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Steelsnout" }
