quests[38702] = { id = 38702, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Dead Warrior's Helmet" }
quests[38703] = { id = 38703, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Scout Rifle" }
quests[38704] = { id = 38704, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Forgotten Iron Horde Supplies" }
quests[38705] = { id = 38705, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Essence of Elements" }
quests[38708] = { id = 38708, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Reinigung des Flusses" }
quests[38709] = { id = 38709, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Cave Keeper" }
quests[38710] = { id = 38710, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine dringende Zusammenkunft", description = "Eine Entscheidung von beträchtlicher Tragweite muss gefällt werden, {name}.\n\nDie Legion hat unsere Streitkräfte an der Verheerten Küste vernichtend geschlagen. Die mächtigste Armee, die diese Welt je gekannt hat, wurde in wenigen Augenblicken eingeäschert.\n\nWir müssen alle zusammenrufen, die noch genug Entschlossenheit besitzen, unsere Heimat zu retten. Travard von Tyrs Wache und Orik Treuherz haben bereits Pläne diesbezüglich geschmiedet, aber wir dürfen sie nicht allein lassen.\n\nBitte sucht sie auf und bringt sie zu Krasus' Landeplatz, damit wir gemeinsam entscheiden können.", sourceObjective = "Holt Travard und Orik Treuherz, und findet Euch dann mit ihnen bei Lord Maxwell Tyrosus an Krasus' Landeplatz ein.", completion = "Danke für Eure Hilfe bei dieser Zusammenkunft, {name}. Gemeinsam sind wir stark.", sourceObjectiveStatus = "unverified-source-field" }
quests[38711] = { id = 38711, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Signet des Wächters", description = "Der Nachtelf trug ein Signet bei sich, in das das Wappen der Wächter eingraviert ist.\n\nDer Ring aus einem silbrigen, unzerbrechlichen Metall scheint im Laufe der Zeit abgenutzt worden zu sein, als hätte ihn sein Besitzer immer wieder geistesabwesend durch die Finger gleiten lassen.", sourceObjective = "Bringt das Signet des Wächters zu Jarod Schattensang.\n\nBereitgestellter Gegenstand:", completion = "<Jarod starrt den Ring eine gute Minute lang an, bevor er seine Finger darum schließt und ihn in seine Tasche gleiten lässt.>\n\nDas ist Maievs Ring. Sie würde sich niemals freiwillig von ihm trennen.\n\nSie muss sich in der Rabenwehr befinden!", sourceObjectiveStatus = "unverified-source-field" }
quests[38712] = { id = 38712, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Houndmaster Ely" }
quests[38714] = { id = 38714, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Maievs Spur", description = "Das Festungsgelände liegt gleich da vorn. Das Gebiet ist recht weitläufig, aber wenn wir uns aufteilen, sollten wir das hinbekommen.\n\nSucht Ihr die Kerkerzellen, die Schmiede und den Wachturm nach Anzeichen auf Maiev ab. Ich werde die oberen Wälle absuchen und treffe Euch dann auf der anderen Seite der Festung.", sourceObjective = "Durchsucht die Schmiede, die Säblergehege und den Wachturm.", progress = "Wir werden diese Gegend gründlich absuchen.", completion = "Gute Arbeit, {name}. Zweifellos haben sie Maiev bereits in die Kerkerzellen unterhalb des Turms gebracht.", sourceObjectiveStatus = "unverified-source-field" }
quests[38715] = { id = 38715, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rabenwehrwache", description = "Die Rabenwehr ist nicht mehr so, wie ich sie einst kannte. Mit ihren eingefallenen Mauern ist sie nur noch ein Schatten ruhmreicherer Zeiten.\n\nWenn Lord Rabenkrone zurückgekehrt ist, dann werden ihn sicher seine früheren Offiziere begleiten.\n\nKester Weitsucher, der Hauptmann der Wache.\n\nTrelan Schildbrecher, ein Streitkolbenmeister ohnegleichen.\n\nStarlys Starkbogen, die Pfeile mit verbundenen Augen spalten konnte.\n\nWenn wir in den Turm selbst eindringen wollen, müssen sie zuvor eliminiert werden.", sourceObjective = "Tötet Kester Weitsucher, Trelan Schildbrecher und Starlys Starkbogen.", completion = "Ich danke Euch, {name}. Mögen ihre Geister in Frieden ruhen.", sourceObjectiveStatus = "unverified-source-field" }
quests[38716] = { id = 38716, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rabenwehr", description = "In der Kiste, unter verschiedenem Krimskrams verborgen, befindet sich ein Signet mit einem unverwechselbaren Wappen.\n\nDer Ring aus einem silbrigen, unzerbrechlichen Metall scheint im Laufe der Zeit abgenutzt worden zu sein, als hätte ihn sein Besitzer immer wieder geistesabwesend durch die Finger gleiten lassen.", sourceObjective = "Bringt das Signet des Wächters zu Jarod Schattensang.", sourceObjectiveStatus = "unverified-source-field" }
quests[38717] = { id = 38717, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kerker der Rabenwehr", description = "Ich bin nicht den ganzen Weg hierhergekommen, um sie im letzten Moment noch zu verlieren.\n\nMaiev muss sich in den Kerkerzellen unterhalb der Rabenwehr befinden.\n\nIch habe mich da oben umgesehen: Der Kerkereingang wird von einem Furcht erregenden Kerkermeister bewacht.\n\nIch werde mich vorbeischleichen und die Wachen im Inneren ausschalten. Besiegt Ihr Araxxas, nehmt ihm die Schlüssel ab und trefft mich dann drinnen.", sourceObjective = "Tötet Araxxas und nehmt die Gefängnisschlüssel an Euch.", progress = "Habt Ihr die Schlüssel?", completion = "Gut. Mit diesen Schlüsseln sollten wir alle Kerkerzellen aufsperren können.", sourceObjectiveStatus = "unverified-source-field" }
quests[38718] = { id = 38718, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kur'talos Rabenkrone", description = "Lord Rabenkrone war ein furchtloser Anführer, ein gestandener Befehlshaber, ein aufrichtiger und ehrenvoller Mann und ein Lehrmeister und Beschützer seines Volkes.\n\nMalfurion, Illidan, Tyrande und ich... Wir waren noch jung, als er uns half, unser Schicksal in die Hand zu nehmen.\n\nViele Legenden ranken sich um das Siegel seines Hauses. Lasst Euren Blick für einen Moment auf dem Siegel über seiner ehemaligen Ruhestätte verweilen. Danach werde ich Euch mehr über sein Vermächtnis erzählen.", sourceObjective = "Betrachtet das Siegel von Rabenkrone.", completion = "Die angreifenden Geister haben von ihrem Herrn und Meister gesprochen. Ich fürchte, dass die Legion Rabenkrone wiedererweckt hat, damit er ihr dient. Welcher Preis für eine solch schändliche Tat bezahlt wurde, vermag ich nicht zu sagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[38719] = { id = 38719, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freiheit für die Illidari", description = "<Der Dämonenjäger der Illidari blutet aus mehreren grässlichen Wunden. Offensichtlich ist er hier zum Sterben zurückgelassen worden.>\n\nIm Gefängnis sind noch drei meiner... <hust>... Kameraden.\n\nWir sind auf unserer Patrouille hier in einen Hinterhalt geraten.\n\nFür mich besteht keine Hoffnung mehr, aber bitte rettet die anderen.", sourceObjective = "Befreit Sirius Schwarzschwinge, Cassiel Nachtdorn und Asha Rabenruf.", completion = "Die anderen Illidari haben es nicht geschafft. Ich aber verdanke Euch mein Leben. Eins habe ich während meiner Zeit im Gefängnis gelernt: Die Dämonen in Rabenwehr müssen sterben.", sourceObjectiveStatus = "unverified-source-field" }
quests[38720] = { id = 38720, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Grund zu bleiben", description = "Elisandes Überfall auf das Mondsichelforum kam so überraschend, dass kaum jemand reagieren konnte. Viele meiner Leute sind tot oder in Gefangenschaft.\n\nEinige von ihnen könnten diesem Gemetzel entkommen sein. Wir müssen sicherstellen, dass niemand von ihnen zurückbleibt.\n\nIch möchte, dass Ihr in den Häusern in der Umgebung nach Überlebenden sucht. Sorgt dafür, dass sie fliehen, bevor sie entdeckt werden, und teilt ihnen mit, dass es keinen Grund gibt, hierzubleiben.\n\nHier ist es nicht sicher, solange Elisande ihre Wahnsinnsherrschaft aufrechterhält.", sourceObjective = "Evakuiert Überlebende am Mondsichelforum und in der Sirenenwacht.", completion = "Wie ich sehe, habt Ihr ein paar Überlebende gefunden. Gut, jetzt bin ich etwas erleichtert.", sourceObjectiveStatus = "unverified-source-field" }
quests[38721] = { id = 38721, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leutnant des Turms", description = "All Eure Vermutungen waren korrekt. Gul'dan hat Lord Rabenkrone und seine geisterhafte Armee aus dem Grab erweckt. Jetzt dienen sie der Legion und bewachen die Geheimnisse des Turms.\n\nWährend Rabenkrone von oben das Kommando führt, hat Leutnant Desdel Sternauge die Aufsicht über den Kerker.\n\nEr hat mich die letzten Monde über gefoltert, aber ich blieb unbeugsam.\n\n<Maiev lässt einen Finger über ihre geschwungene Klinge gleiten.>\n\nSein Leben muss enden.", sourceObjective = "Tötet Desdel Sternauge.", completion = "Lord Sternauge entstammt einer adligen Familie, doch in Kriegsangelegenheiten konnte er es nie mit Rabenkrone oder meinem Bruder aufnehmen.\n\nJetzt, wo er besiegt ist, können wir uns seinem Befehlshaber zuwenden.\n\nDas wird allerdings keine einfache Aufgabe. Wir müssen erst unsere Kraft sammeln, bevor wir uns Lord Rabenkrone selbst stellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[38723] = { id = 38723, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haltet Gul'dan auf!", description = "Nach seinem Tod im Schwarzen Tempel brachten wir Illidans leblose Hülle hierher, wo sie bis ans Ende der Zeit ruhen sollte.\n\nGul'dan konnte unsere Verteidigung durchbrechen und versucht nun, den Körper des Verräters an sich zu reißen.\n\nSelbst im Tod kann Illidans Körper der Legion von Nutzen sein. Gul'dan DARF ihn nicht bekommen.", sourceObjective = "Betretet den Kerker des Verräters. Tötet dort Zermalmer und Hammer und beansprucht ihre Teufelskraft.", completion = "Ausgezeichnet. Ihr habt diesen Schlägern die Kraft rauben können. Seht nur, wie stark Ihr jetzt seid!", sourceObjectiveStatus = "unverified-source-field" }
quests[38724] = { id = 38724, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bruderliebe", description = "Maiev muss irgendwo in diesem Kerker sein. Auf dem Weg hierher fand ich ihre abgestreifte Rüstung.\n\nWir sollten uns aufteilen, um die Zellen schneller abzusuchen.\n\nWir müssen sie finden.", sourceObjective = "Sucht Maiev Schattensang im Kerker der Rabenwehr.\n\nBereitgestellter Gegenstand:", completion = "<Maievs Gesicht ist blutunterlaufen, ihre Lippen sind aufgeplatzt und ihr Körper ist mit Narben übersät. Sie sieht mager und erschöpft aus, aber ihre Bewegungen sind immer noch kraftvoll.>\n\nWochenlang haben sie versucht, mich zu brechen, diese Amateure!\n\nIch habe geschwiegen, die Minuten gezählt, ihre Schritte geschätzt und den Stimmen außerhalb meiner Zelle gelauscht.\n\nIch habe auf meine Chance gewartet, um meinen Peinigern zu entkommen und mich zu rächen.\n\nUnd jetzt bringt Ihr mir meine Rüstung UND mein Schwert. Ich werde meine Rettung mit einem Blutvergießen feiern.\n\n<Maiev lächelt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[38725] = { id = 38725, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zum Fäulnishort", description = "Einer der Dämonen, die ich verhört habe, enthüllte eine besonders delikate Information. Es scheint, im Vulkan lebt eine Wichtelmutter, die Geheimnisse der Legion niederschreibt.\n\nKor'vas ist losgezogen, um diesen Dämon zu finden und ihre Geheimnisse für uns sicherzustellen.", sourceObjective = "Trefft Euch mit Kor'vas Blutdorn am Fäulnishort.", completion = "{name}. Ich habe sie gefunden.", sourceObjectiveStatus = "unverified-source-field" }
quests[38726] = { id = 38726, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Magwia" }
quests[38727] = { id = 38727, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stoppt das Bombardement", description = "Jaces Schutzzauber werden nicht mehr lange halten. Wir brauchen jemanden, der dort raus geht und sicherstellt, dass diese Verwüster der Legion kaltgestellt werden.\n\n<Kayn wirft Euch einen vielsagenden Blick mit seinen magisch verbesserten Augen zu.>", sourceObjective = "Zerstört die Verwüster der Legion.", completion = "Wahre Anführer sieht man selten und noch seltener sieht man sie an der Front.\n\nWir sind jetzt bereit für den Sturm auf die Kommandozentrale von Brutkönigin Tyranna.", sourceObjectiveStatus = "unverified-source-field" }
quests[38728] = { id = 38728, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schlüsselstein", description = "{name}, Brutkönigin Tyranna ist dort im Befehlsstand. Die anderen haben ihn bereits gestürmt. Sie besitzt den Sargeritschlüsselstein.\n\nEndlich ist das, wofür wir so viel geopfert haben, zum Greifen nah.", sourceObjective = "Tötet Brutkönigin Tyranna und entreißt ihr den Sargeritschlüsselstein. Trefft Euch danach mit den anderen unten in der Portalkammer.", progress = "{name}, seid Ihr bereit?", completion = "Nun, da sich der Schlüsselstein in unserem Besitz befindet, gibt es nur noch eins zu tun...", sourceObjectiveStatus = "unverified-source-field" }
quests[38729] = { id = 38729, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zum Schwarzen Tempel", description = "Schnell, {name}, benutzt den Sargeritschlüsselstein.\n\nWir müssen zurück zum Schwarzen Tempel gelangen, bevor es zu spät ist.", sourceObjective = "Benutzt den Sargeritschlüsselstein, um das Teufelsportal zu aktivieren und zum Schwarzen Tempel zurückzukehren.", completion = "<Während Ihr die Macht des Sargeritschlüsselsteins beschwört, wird das Teufelsportal mit einer absonderlichen Energie überflutet.\n\nEs wird Zeit, triumphierend zum Schwarzen Tempel zurückzukehren und Lord Illidan dabei zu unterstützen, die Invasoren aus Azeroth und Shattrath zurückzuschlagen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[38730] = { id = 38730, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Farm Defense" }
