quests[38742] = { id = 38742, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Crazy BH Chief Skull" }
quests[38743] = { id = 38743, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schicksal von Val'sharah", description = "Malfurion, mein Geliebter... Es bricht mir das Herz, doch ich kann ihm nicht dorthin folgen, wo er hingeht.\n\nIch schwor meiner Göttin Elune die Treue. Ich muss ihre Tempel und Lande mit all meiner Kraft verteidigen. Ich kann nicht untätig zusehen, wenn mein Orden in Gefahr ist.\n\nMöge sie dich stets ihre Gnade erfahren lassen, Malfurion.\n\n<Tyrande wendet sich mit feucht glänzenden Augen ab.>", sourceObjective = "Verteidigt den Tempel von Elune.", completion = "Dies wird als einer der dunkelsten Tage unserer Welt in die Geschichte eingehen. Aber noch gibt es Hoffnung. Elunes Licht hat unsere Entschlossenheit gestärkt.", sourceObjectiveStatus = "unverified-source-field" }
quests[38744] = { id = 38744, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Stormheim - Treasure 030 - Statue - ZTO" }
quests[38746] = { id = 38746, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Iron Front Captain 1" }
