quests[38752] = { id = 38752, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Szirek" }
quests[38753] = { id = 38753, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Spur des Dämons", description = "Malfurion ist in der Nähe. Ich kann ihn spüren.\n\nSeht auf dem Gipfel von Andu'talah nach, und ich durchsuche weiterhin den Wald.\n\nBeeilt Euch, {name}. Die Zeit drängt!", sourceObjective = "Sucht nach Malfurion Sturmgrimm.", completion = "Mein Gatte, Malfurion. Was ist aus ihm geworden?!\n\nAntwortet!", sourceObjectiveStatus = "unverified-source-field" }
quests[38754] = { id = 38754, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Axe of the Weeping Wolf" }
