quests[38757] = { id = 38757, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Eye of Grannok" }
quests[38758] = { id = 38758, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Dead Orc Captain's Chest" }
quests[38759] = { id = 38759, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst sie frei", description = "Cyana ging hinunter zur Geschmolzenen Küste. Sie wollte ein paar Dämonenjägern helfen, die vor uns durch das Portal kamen. Doch dabei ist etwas schiefgelaufen.\n\nDiesem Inquisitor zufolge werden sie alle von einem bisher unbekannten Dämonen festgehalten, den man \"Wärter\" nennt. Dieses Ding saugt seinen Opfern die Seele aus. Ich weiß nicht, wie lange sie noch durchhalten können.", sourceObjective = "Einige Eurer Dämonenjäger sind in ernster Gefahr. Findet den seelengeschliffenen Schlüssel und holt sie da raus.", progress = "Einige unserer {class} sind verschwunden. Habt Ihr sie an der Geschmolzenen Küste finden können?", completion = "Ein Wärter hat ihre Seelen vollständig ausgesaugt?\n\nDie Streitkräfte der Brennenden Legion an diesem Ort sind weit mächtiger und brutaler als alles, was wir bisher gesehen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[38760] = { id = 38760, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Captain's Booty 1" }
quests[38761] = { id = 38761, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Captain's Booty 2" }
quests[38762] = { id = 38762, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Captain's Booty 3" }
quests[38763] = { id = 38763, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormheim - Vignette - Titan Vault" }
quests[38764] = { id = 38764, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Murktide Alpha" }
quests[38765] = { id = 38765, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auftritt der Illidari: Die Shivarra", description = "Unsere Dämonenherrinnen der Shivarra warten im Schwarzen Tempel. Es ist riskant, sie hierher zu bringen... schließlich waren sie einmal Teil der Brennenden Legion. Trotzdem... sie gehören zu den unerbittlichsten Kämpfern unter Lord Illidans Kommando.\n\n<Jace sieht Euch lange wortlos an.>\n\nIch fürchte, jemand wird für ihre Herbeirufung das ultimative Opfer bringen müssen.", sourceObjective = "Speist den Toraktivator der Legion mit einer kraftvollen Seele und ruft damit Eure Truppen der Shivarra herbei.", completion = "Grausam. Doch Dämonenjägern sind Opfer nicht fremd. Wir haben alles gegeben, um zu werden, was wir heute sind.\n\nDie Legion wird fallen. Wir erwarten Eure Befehle, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[38766] = { id = 38766, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überrennt sie, bevor sie Euch überrennen", description = "Der Verdammniswachenkommandant und seine Königin erfordern unsere Aufmerksamkeit. Seine Eredar beschwören Unmengen an Verstärkungstruppen.\n\nWir müssen dieser Bedrohung ein Ende setzen, bevor die Legion unseren Vorposten oben im Vulkan überrennt.\n\nUnd darüber hinaus könnt Ihr bei dieser Gelegenheit seine dämonische Kraft stehlen.", sourceObjective = "Vernichtet Verdammniskommandant Beliash und macht Euch seine Kraft zu eigen.", completion = "Die Flut von Dämonen hat sich bereits deutlich abgeschwächt.\n\nIch spüre die Energie der Verdammniswache. Ihr seid bereits mächtiger geworden.", sourceObjectiveStatus = "unverified-source-field" }
quests[38767] = { id = 38767, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nightmaul" }
