quests[38776] = { id = 38776, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Sacrificial Blade" }
quests[38777] = { id = 38777, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Probe eines Leysteinvorkommens", description = "So eine Art Erz habt Ihr noch nie gesehen.\n\nDurch das Metall hindurch wandert ein mystischer Schimmer in aufwendigen, nicht nachvollziehbaren Mustern. Eure Lehrerin in Dalaran wäre daran sicher sehr interessiert.", sourceObjective = "Bringt die Probe eines Leysteinvorkommens zu Mama Buddel in Dalaran.", progress = "Was habt Ihr denn da, mein Junge?", completion = "So leicht. Und vor allem so hübsch! Erinnert mich ein bisschen an Elementium.\n\nWenn Ihr mehr davon seht, dann versucht, es entlang der Maserung zu bearbeiten. Dann verschwendet Ihr nicht so viel davon.", sourceObjectiveStatus = "unverified-source-field" }
quests[38778] = { id = 38778, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dreht die Schlüssel", description = "Meine Wurzeln verwittern... meine Äste sterben ab...\n\nDie Knochensprecher wollen den Runenwald verstummen lassen. Die Runensteine sind der Schlüssel...\n\nDreht die Runensteine... Befreit mich von den Fesseln...", sourceObjective = "Aktiviert die Runensteine im Runenwald.", completion = "Dann waren es Eure Schritte, die ich im Wald verspürte, als die Runensteine mich aus ihrem Griff entließen?\n\nIch danke Euch, Fremder.", sourceObjectiveStatus = "unverified-source-field" }
quests[38779] = { id = 38779, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Hidden BH Chest" }
quests[38780] = { id = 38780, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Val'sharah - River - Vignette: Thondrax - TRACKING - twh" }
quests[38781] = { id = 38781, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Val'sharah - Treasure 016- Andu'talah - twh" }
