quests[38783] = { id = 38783, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Val'sharah - Treasure 018 - Andu'talah - twh" }
quests[38784] = { id = 38784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Probe eines Leysteinflözes", description = "Dieses Erz hat ganz eindeutig einige der latenten Leyenergien der Verheerten Inseln absorbiert. Es fühlt sich kalt an und reflektiert das Licht in seltsamen, verspielten Winkeln.\n\nDas sollte sich Eure Lehrerin in Dalaran ansehen.", sourceObjective = "Bringt die Probe eines Leysteinflözes zu Mama Buddel in Dalaran.", progress = "Und was habt Ihr mir diesmal mitgebracht?", completion = "Jetzt seht Euch das einmal an! Was für eine Schönheit!\n\nDiese Art Erz müsst Ihr sehr vorsichtig behandeln, mein Junge. Da braucht es keine harten Schläge, sondern nur ein leichtes Klopfen auf die richtige Stelle, und schon erhaltet Ihr viel mehr Erz als ein Anfänger.", sourceObjectiveStatus = "unverified-source-field" }
quests[38785] = { id = 38785, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Probe lebenden Leysteins", description = "Das ist kein normaler Leystein. Dieser hier ist viel lebendiger und schimmert in komplexen, beinah hypnotischen Mustern. Man könnte sich glatt darin verlieren.\n\nEure Lehrerin in Dalaran würde sicher gern einen Blick darauf werfen.", sourceObjective = "Bringt die Probe lebenden Leysteins zu Mama Buddel in Dalaran.", progress = "Ooohhh...!", completion = "Das ist doch mal etwas ganz Besonderes! Ihr habt das von einer dieser Felskreaturen da unten?\n\nEs scheint aber nur ein Teil des Rumpfes zu sein. Bringt nächstes Mal auch die Arme und den Kopf mit. Da ist jede Menge gutes Fleisch dran.", sourceObjectiveStatus = "unverified-source-field" }
quests[38786] = { id = 38786, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Respekt", description = "Leystein ist ein sensibles Erz. Unsere Schmiede können ihm große Kräfte entlocken, aber wir Bergarbeiter müssen respektvoll damit umgehen, weil sich seine Kräfte sonst ins Innere zurückziehen.\n\n<Der Tauren überreicht Euch eine Spitzhacke aus GLAS.>\n\nVerwendet die hier, wenn Ihr das nächste Mal Leysteinerz abbaut. Sie zerbricht, wenn Ihr zu hart zuschlagt. DAS ist der Respekt, den Ihr dem Leystein zeigen müsst.", sourceObjective = "Verwendet 35-mal Ronos' Glasspitzhacke zum Abbauen von Leystein.", progress = "Ihr habt doch wohl etwa nicht meine Spitzhacke zerbrochen, oder?", completion = "Ihr habt schon so viel gelernt, {name}.\n\nBleibt noch eine Weile. Ich werde Euch eine Geschichte erzählen.", sourceObjectiveStatus = "unverified-source-field" }
quests[38787] = { id = 38787, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Legende von Rethu Eisenhorn", description = "Vor langer, langer Zeit kam ein Tauren namens Rethu in dieses Land. Was er entdeckte, war die Grundlage für die Arbeit aller Bergarbeiter.\n\nWenn Ihr mehr über den Bergbau wissen wollt, müsst Ihr zunächst mehr über Rethu lernen.", sourceObjective = "Sprecht mit Ronos Eisenhorn, um mehr über die Geschichte von Rethu Eisenhorn zu erfahren.", progress = "Hört gut zu, {name}.", completion = "Der Widerhall aus Rethus Zeit ist in diesem Land noch immer zu hören, {name}. Achtet auf seinen Einfluss, wenn Ihr da draußen Euren Tätigkeiten nachgeht.", sourceObjectiveStatus = "unverified-source-field" }
quests[38788] = { id = 38788, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Magic Brazier" }
quests[38789] = { id = 38789, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rethus Tagebuch", description = "Euch fällt ein Fetzen Papier auf, der aus dem Geröll hervorlugt.\n\nIhr räumt die Steine vorsichtig zur Seite und entdeckt die Überreste einer alten Schriftrolle. Die Taurenhandschrift ist etwas archaisch, aber ein Wort könnt Ihr entziffern:\n\n\"Rethu\".", sourceObjective = "Bringt die zerfledderte Tagebuchseite zu Ronos Eisenhorn auf dem Hochberg.", progress = "Seid gegrüßt, Bergarbeiter. Was habt Ihr denn da?", completion = "Das... das ist ja unglaublich! Ein Teil von Rethus Bergbautagebuch!\n\nSeht Euch das an, Bergarbeiter... Hier sind Einzelheiten zu dem Leysteinabbauverfahren, an dem er gearbeitet hat...", sourceObjectiveStatus = "unverified-source-field" }
quests[38790] = { id = 38790, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rethus Spitzhacke", description = "Dieses Flöz wurde bereits zuvor bearbeitet. Die typischen diagonalen Spuren einer Spitzhacke sind deutlich zu erkennen.\n\nAls Ihr hinunterschaut, entdeckt Ihr die Spitzhacke am Boden... mit zerbrochenem Schaft und ganz stumpf von vielen Jahren der Verwendung.\n\nIn den Schaft ist ein vertrauter Name eingeritzt:\n\n\"Rethu\".", sourceObjective = "Bringt die abgewetzte Spitzhacke zu Ronos Eisenhorn auf dem Hochberg.", progress = "Was habt Ihr denn da, Bergarbeiter?", completion = "Rethus persönliche Spitzhacke...\n\nAlso, zumindest eine von ihnen. Man sagt, er habe wöchentlich eine davon verschlissen.\n\nUnd trotzdem habe ich noch nie eine mit eigenen Augen gesehen. Seht Euch die Abnutzungsspuren an, Bergarbeiter. In welchem Winkel er ansetzte und mit welcher Kraft er zuschlug... Wir können so viel durch das Studium dieses Artefakts erfahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[38791] = { id = 38791, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rethus Horn", description = "Die Leiche dieser Felsbestie hatte ein ungewöhnliches Schmuckstück zu bieten: das Bruchstück eines Taurenhorns.\n\nEs ist ganz offensichtlich sehr alt, aber seine Farbe und Form erinnern Euch an Ronos Eisenhorn in der Eisenhornenklave.", sourceObjective = "Bringt das Hornbruchstück zu Ronos Eisenhorn auf dem Hochberg.", progress = "Was... was ist das denn, Bergarbeiter?", completion = "Das... das kann doch nicht sein...\n\nDas stammt von einem Mitglied meines Stammes, {name}. Wo habt Ihr das gefunden?\n\nEine der ersten Geschichten, die wir über Rethu lernen, handelt von dem Tag, an dem er sein Horn in einem Kampf verlor. Man kann nicht mit Sicherheit sagen, dass das hier von ihm stammt, aber... aber...", sourceObjectiveStatus = "unverified-source-field" }
quests[38792] = { id = 38792, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rethus Lektion", description = "He, <Minenarbeiter/Minenarbeiterin>... Zeigt mir mal kurz Eure Hacke.\n\n<Der Tauren schaut sich Eure Bergbauausrüstung an.>\n\nIhr erinnert mich an mich selbst, als ich noch durch dieses Land streifte. Genießt diese Zeit, <Minenarbeiter/Minenarbeiterin>. Sie wird irgendwann vorbei sein.\n\n<Mit einer Verbeugung verschwindet der Geist wieder.>", sourceObjective = "Berichtet Ronos Eisenhorn am Hochberg von Eurer Begegnung.", completion = "Ihr habt während der Bergbauarbeiten da draußen in der Wildnis einen Geist gesehen?\n\nNein, das glaube ich Euch nicht. Man darf nicht zu viel Zeit mit dem Bergbau verbringen, denn das benebelt die Sinne. Das müsst Ihr geträumt haben.\n\nUnd doch... ist etwas anders mit Euch. Ihr habt etwas gelernt. Vielleicht ist an Eurer Geschichte doch etwas dran.", sourceObjectiveStatus = "unverified-source-field" }
quests[38793] = { id = 38793, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rethus Erfahrung", description = "Wisst Ihr, wer ich bin, <Minenarbeiter/Minenarbeiterin>?\n\nVerstehe. Das ist gut. Mein Stamm ehrt seine Vorfahren.\n\nWenn Ihr in das Land des Eisenhornstammes zurückkehrt, dann sagt ihnen, dass wir stolz auf sie niederblicken.", sourceObjective = "Berichtet Ronos Eisenhorn am Hochberg von Eurer Begegnung.", completion = "<Der {race} hört sich Eure Erzählung von der Begegnung mit dem Geist von Rethu Eisenhorn an.>\n\nNormalerweise würde ich Euch nicht glauben, aber... Ich spüre, dass Ihr die Wahrheit sagt. Ihr könnt Euch wirklich glücklich schätzen.\n\nIch bin sehr froh, dass unsere Vorfahren so stolz auf uns sind. Wir haben den richtigen Weg gewählt.\n\nIch danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[38794] = { id = 38794, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rethus Opfer", description = "Bitte hört mich einen Augenblick an, <Minenarbeiter/Minenarbeiterin>. Mir bleibt nicht mehr viel Zeit hier.\n\nIch habe gesehen, wie Ihr um das Erz gekämpft habt, und ich glaube, das ist die ehrenwerteste Art, an einen Stein zu kommen. So hat das Land eine Chance zu kämpfen.\n\nUnd dennoch darf niemand zu kaltherzig werden. Wer zu tief gräbt, wird von dem Land besiegt. Kein Stein ist den Preis wert, den ich zahlen musste.\n\nAber das ist eine andere Geschichte...", sourceObjective = "Berichtet Ronos Eisenhorn am Hochberg von Eurer Begegnung.", completion = "Der Geist von Rethu Eisenhorn? Erzählt mir alles, was er gesagt hat.\n\nEr sagte \"wer zu tief gräbt\"? Ich verstehe... Die Erdenmutter hat ihn zu sich geholt.\n\nDanke, dass Ihr zu mir gekommen seid, Minenarbeiter. Diese Geschichte müssen auch die anderen des Stammes erfahren. Aus ihr können wir viel lernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[38795] = { id = 38795, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Probe eines Teufelsschiefervorkommens", description = "Das ist ein ziemlich finster aussehender Stein.\n\nIhr solltet ihn Eurer Lehrerin in Dalaran zeigen.", sourceObjective = "Bringt die Probe eines Teufelsschiefervorkommens zu Mama Buddel in Dalaran.", progress = "Bringt Ihr mir was Neues mit?", completion = "Das ist kein natürlicher Stein, Bergarbeiter. Er stinkt nach Dämonenblut. Wo habt Ihr den denn gefunden?\n\nErinnert mich ein bisschen an Teufelseisen. Kommt her, ich zeige Euch ein paar Tricks, wie Ihr das Zeug vernünftig abbaut.", sourceObjectiveStatus = "unverified-source-field" }
quests[38796] = { id = 38796, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Probe eines Teufelsschieferflözes", description = "Dieses Erz ist auffallend schwer. Aber was Euch eher beunruhigt, ist, dass es bei Berührung dunkler wird und zischt.\n\nVielleicht kann Eure Bergbaulehrerin in Dalaran etwas dazu sagen.", sourceObjective = "Bringt die Probe eines Teufelsschieferflözes zu Mama Buddel in Dalaran.", progress = "Ihr seht aus, als wärt Ihr fleißig gewesen, Bergarbeiter.", completion = "Das stammt aus einem Flöz bei den Klippen? Denkt daran, Ihr könnt Flöze nicht auf die gleiche Weise abbauen wie normale Vorkommen. Das ist eine ganz andere Sache. Ich werde Euch zeigen, wie das am besten geht.", sourceObjectiveStatus = "unverified-source-field" }
quests[38797] = { id = 38797, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Probe lebenden Teufelsschiefers", description = "Ihr entwickelt langsam einen echten Bergarbeiterinstinkt. Die Brocken der Höllenbestie scheinen nutzbar zu sein.\n\nAber es muss einen Weg geben, noch mehr Erz aus den Dämonenleichen zu gewinnen. Vielleicht weiß Eure Bergbaulehrerin in Dalaran etwas darüber.", sourceObjective = "Bringt die Probe lebenden Teufelsschiefers zu Mama Buddel in Dalaran.", progress = "Was ist das denn?", completion = "Das stammt von einer verdammten Höllenbestie?! Oh, offenbar haben wir hier einen Kampfbergarbeiter!\n\nEin Teil dieses Erzes hat auf dem Weg zurück allerdings seinen Glanz verloren. Nächstes Mal solltet Ihr darauf achten, erst die Schwert- und Zauberspuren glattzuschlagen, bevor Ihr es abbaut.", sourceObjectiveStatus = "unverified-source-field" }
quests[38798] = { id = 38798, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein kleines Opfer", description = "Teufelsschiefer abzubauen heißt, nach dem Blut der Dämonen zu suchen. Und um darin noch besser zu werden, müsst Ihr selbst zu einem Teil Dämon werden.\n\nWas schaut Ihr denn so? Ihr habt doch selbst gesagt, dass Ihr bereit seid, Opfer zu bringen.\n\nZum Glück für Euch kenne ich mich auf diesem Gebiet aus. Vertraut mir, ich setze Euch keiner Gefahr aus.\n\nSeid Ihr bereit?", sourceObjective = "Gestattet Teufelsschmiedin Nal'ryssa, Euch drei Splitter Teufelsschiefer zu implantieren.", progress = "Verschwendet nicht meine Zeit, Bergarbeiter.", completion = "Es ist vollbracht.\n\nStreckt Euch mal ein bisschen.\n\nIhr werdet in den nächsten Wochen vielleicht hin und wieder das Verlangen haben, Welten zu verbrennen und Chaos zu verbreiten. Versucht, diesem Begehren zu widerstehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[38799] = { id = 38799, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Finsterherzdickicht: Nal'ryssas Schwestern", description = "Ich stamme aus einer Familie von Bergarbeitern. Ich war die jüngste von vier Schwestern.\n\nIch sage \"war\", weil wir die anderen drei verloren haben.\n\nZwei von ihnen sind zu weit gegangen und haben ihren Körpern so viel Teufelsschiefer zugemutet, dass sie dem Willen Sargeras' erlegen sind. Jetzt sind sie mehr Dämonen als Elfen.\n\nUnd von der dritten habe ich schon lange nichts mehr gehört. Zuletzt wurde sie beim Finsterherzdickicht gesehen.\n\nIch befürchte, dass auch sie verloren ist... auf die ein oder andere Weise.", sourceObjective = "Findet Lyrelles Siegelring beim Finsterherzdickicht.", progress = "Irgendwelche Hinweise auf meine Schwester?", completion = "Ja, das ist der Ring meiner Schwester.\n\nDass Ihr ihn bei einer Dämonenleiche gefunden habt, bedeutet, dass sie im Kampf gefallen oder wie meine Schwestern selbst zu einem Dämon geworden ist.\n\nDanke, dass Ihr ihn mir gebracht habt. Wir brauchen hier an der Front eigentlich alles Material, das wir bekommen können... aber das hier kann ich entbehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[38800] = { id = 38800, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rin'thissas Auge", description = "Ihr entdeckt ein Humanoidenauge, dass auf seltsame Weise in das Teufelsschiefervorkommen eingebettet ist.\n\nEs scheint zu leben und würde Euch wohl gerne zublinzeln, wenn es Augenlider hätte.\n\nDies sollte sich ein Bergbauexperte anschauen.", sourceObjective = "Bringt das erzgebundene Auge zu Teufelsschmiedin Nal'ryssa in Suramar.", progress = "Ist... ist das...?", completion = "Ja, das ist es... Das ist das Auge meiner Schwester Rin'thissa.\n\nWie töricht sie war, ihr eigenes Auge herauszuschneiden und durch einen Erzbrocken zu ersetzen. Das war zu viel... Jetzt ist sie dem dämonischen Wahnsinn anheimgefallen.\n\nLernt aus ihren Fehlern, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[38801] = { id = 38801, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lyrelles rechter Arm", description = "Ihr reibt Euch die Augen, aber Ihr habt Euch nicht getäuscht. Komplett im Teufelsschieferflöz eingeschlossen befindet sich der Arm einer Frau.\n\nDer blutlose Arm zuckt noch. Wo früher Adern waren, sind jetzt Spuren dämonischer Energie zu sehen.\n\nDas wird Teufelsschmiedin Nal'ryssa sicher sehen wollen.", sourceObjective = "Bringt den abgetrennten Arm zu Teufelsschmiedin Nal'ryssa in Suramar.", progress = "Lyrelle, nein...", completion = "Er gehörte meiner Schwester Lyrelle.\n\nJetzt weiß ich, was passiert ist. Sie brauchte den Siegelring nicht mehr, weil sie ihren eigenen Arm gegen einen aus Teufelsschiefer eingetauscht hatte.\n\nSeid Ihr nicht froh, dass wir bei Euch nur drei Splitter verwendet haben?\n\nNehmt Euch das zu Herzen, {name}: Ihr könnt alles verlieren, wenn Ihr Euch von der Gier überwältigen lasst. Die arme Lyrelle hat für uns alle den Preis bezahlt.", sourceObjectiveStatus = "unverified-source-field" }
quests[38802] = { id = 38802, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ondris noch schlagendes Herz", description = "Was wie ein weiterer Brocken Teufelsschiefer aussah, ist in Wahrheit ein Humanoidenherz. Es ist vollständig in Gestein eingebettet und nicht mehr mit Blut, sondern einer grässlichen, dämonischen Substanz gefüllt.\n\nEs scheint nicht zu der Bestie zu gehören, aus der Ihr es herausgeschnitten habt... die Höllenbestie scheint es vielmehr als Andenken bei sich getragen zu haben. Glücklicherweise habt Ihr es nicht mit der Spitzhacke beschädigt.\n\nIhr solltet es Teufelsschmiedin Nal'ryssa zeigen.", sourceObjective = "Bringt das erzgepresste Herz zu Teufelsschmiedin Nal'ryssa in Suramar.", completion = "Meine Schwester Ondri war die Erste von uns, die mit dem Bergbau begann. Und sie war auch die Erste, die verloren war. Irgendein Schreckenslord der Nathrezim hatte sie überzeugt, ausgerechnet ihr Herz durch einen Teufelsschieferbrocken zu ersetzen.\n\nIch habe diesen Schreckenslord persönlich getötet, aber ich konnte das Herz nicht finden. Das hier muss es sein.\n\nTut mir leid, große Schwester... Ihr sollt nicht umsonst gestorben sein. Wir werden aus Euren Fehlern lernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[38803] = { id = 38803, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rin'thissa", description = "Meine Schwester Nal'ryssa hat sich in Euch verkrallt, nicht wahr?\n\nSie ist schwach und weiß nicht das Geringste über den Bergbau. Sie hatte immer Angst vor dem letzten Schritt. Wahres Wissen bietet nur der Großmächtige, der Gott der Dämonen und Flammen.\n\nIhr wollt die Wahrheit über den Bergbau erfahren? Dann begebt Euch in die nordwestliche Ecke Suramars und sprecht dort meinen Namen aus:\n\nRin'thissa.", sourceObjective = "Beschwört und besiegt Rin'thissa.", completion = "Die Seele meiner Schwester ruht jetzt in Frieden und dafür möchte ich Euch danken.\n\nRin'thissa war schon immer sehr... einnehmend. Es war richtig, dass Ihr ihre Einladungen abgelehnt und sie vor allem von ihrer dämonischen Besessenheit befreit habt. Ihr habt viel gelernt, seit wir uns das erste Mal sahen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[38804] = { id = 38804, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lyrelle", description = "Nun, <Bergarbeiter/Bergarbeiterin>, Ihr seid noch immer an Euer schwächliches, verwesendes Fleisch gebunden.\n\nUm eins zu werden mit den dämonenberührten Steinen dieses Landes, müsst Ihr Eure Hülle abstreifen und Euch einer dunkleren Macht hingeben.\n\nSchließt Euch uns an. Bringt Euren gebrechlichen Körper zur Teufelsseelenbastion und sprecht dort meinen Namen aus:\n\nLyrelle.", sourceObjective = "Beschwört und besiegt Lyrelle.", completion = "Arme Lyrelle.\n\nIch mache Euch keine Vorwürfe, dass Ihr sie getötet habt, {name}. Ich danke Euch vielmehr und hoffe, Ihr werdet mit mir dasselbe tun, sollte ich je diesen verderbten Weg einschlagen.\n\nIch bitte Euch nur, etwas aus dieser schmerzhaften Erfahrung zu lernen. Ich hasse den Gedanken, dass ihr Tod sinnlos gewesen sein soll.", sourceObjectiveStatus = "unverified-source-field" }
quests[38805] = { id = 38805, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ondri", description = "Ihr seid ein Nichts gegen mich. Ihr haltet Euch selbst für so gestählt, erfahren... und sogar heldenhaft. Ha!\n\nIhr habt keine Vorstellung, was ich durchgemacht habe. All die Leiden, all die Opfer, die ich erbracht habe. Und das nur im Namen meiner Berufung!\n\nJa, genau wie Ihr beschäftige ich mich mit dem Bergbau. Wenn Ihr etwas von mir lernen wollt, dann kommt zum Purpurdickicht in Suramar und sprecht dort meinen Namen aus:\n\nOndri.", sourceObjective = "Beschwört und besiegt Ondri.", completion = "Die Schreckenszeit meiner Schwester ist damit zu Ende.\n\nSie war immer die Klügste von uns. Es ist traurig, dass es so enden musste. Ich bin mir sicher, dass wir viel von ihr hätten lernen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[38806] = { id = 38806, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infernoschwefelprobe", description = "Dieses Erz... stinkt... fürchterlich. Der kombinierte Gestank von Schwefel und einer verwesenden Leiche.\n\nIrgendjemand wird sicher etwas damit anfangen können.\n\nVielleicht möchte Eure Bergbaulehrerin in Dalaran mal ihre Nase daran halten.", sourceObjective = "Bringt die Infernoschwefelprobe zu Mama Buddel in Dalaran.", progress = "Entschuldigt, ich muss wohl... Moment! Kommt dieser Gestank etwa von EUCH?!", completion = "Dieser geruchsintensive Brocken, den Ihr mitgebracht habt... das ist Infernoschwefel, oder?\n\nFaszinierend.\n\nIch hab schon viel über das Zeug gehört, aber es noch nie mit eigenen Augen gesehen.\n\nIch muss es näher untersuchen. In der Zwischenzeit könnt Ihr Euch hiermit beschäftigen. Das ist alles, was ich über dieses sehr seltene Erz weiß.", sourceObjectiveStatus = "unverified-source-field" }
quests[38807] = { id = 38807, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infernoschwefelanalyse", description = "Um Infernoschwefel abbauen zu können, müssen wir erst verstehen, wie dieses Erz entstanden ist. Zurzeit forschen drei meiner Schüler für mich an verschiedenen Erzen in unterschiedlichen Teilen der Welt.\n\nFindet Forinn Steinherz in Tiefenheim, Rhol Landers im Schattenhochland und Krul Felshorn in Eiskrone und tragt alle Informationen zusammen, die sie über die Erze in diesen Gegenden gesammelt haben.", sourceObjective = "Sammelt die Berichte von Mama Buddels Schülern in Eiskrone, Tiefenheim und dem Schattenhochland ein.", progress = "Was habt Ihr denn da, mein Junge?", completion = "Faszinierend...", sourceObjectiveStatus = "unverified-source-field" }
quests[38808] = { id = 38808, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bjornhjarta", description = "Auch im Jenseits verspüren die Toten noch Gelüste auf die Köstlichkeiten aus ihrem früheren Leben. Für die Könige der Vrykul gibt es nichts Schöneres als Bjornhjarta, ein Festmahl aus geschwollenem Bärenherz.\n\nDie Bären im Runenwald sind wohlgenährt und berühmt für ihr saftiges Fleisch. Begebt Euch auf die Jagd und sucht nach einem geeigneten Herz als Gabe für die alten Herrscher. Einem solchen Geschenk können sie einfach nicht widerstehen.", sourceObjective = "Sammelt 4 geschwollene Bärenherzen von den gierigen Bären im Runenwald.", progress = "Wie war die Jagd, Fremder?", completion = "Das sind schön fette und blutige Herzen.\n\nDie schlafenden Herrscher werden diesem Bjornhjarta-Geschenk nicht widerstehen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[38809] = { id = 38809, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Mushroom Barrel" }
quests[38810] = { id = 38810, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Traumpilz", description = "<Ein Fremder/Eine Fremde>, <der/die> sich dem Urteil der alten Herrscher der Vrykul stellen will? Das ist seltsam. Aber Ihr solltet wissen, dass ihnen Eure Gegenwart nicht gefallen wird.\n\nWenn Ihr unbedingt vor sie treten wollt, könnt Ihr sie mit einem Erweckungsritual heraufbeschwören. Dazu benötigt Ihr aber eine aromatische Substanz zur Verbrennung und ein Geschenk als Opfergabe.\n\nIm Runenwald wächst ein Pilz, der sich als Räucherwerk eignet. Wenn Ihr einige besorgt habt, erkläre ich Euch die weiteren Schritte.", sourceObjective = "Sammelt 8 Seelenkappen im Runenwald.", progress = "Was habt Ihr uns mitgebracht?", completion = "Ja, diese Seelenkappen sollten für das Ritual geeignet sein.\n\nSprecht mich an, wenn Ihr bereit seid, die nächsten Schritte zu erfahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[38811] = { id = 38811, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Tag des Urteils", description = "Ihr habt Euch bis jetzt als sehr findig erwiesen, <Fremder/Fremde>. Wie versprochen werde ich Euch nun das Ritual der Erweckung erklären.\n\nZunächst müsst Ihr die Opfergabe direkt auf das Grab des Herrschers legen, den Ihr erwecken möchtet. Verbrennt dann das Räucherwerk, damit der Duft über das Grab zieht. Wenn Eure Opfergabe angemessen ist, erhebt sich der Herrscher und Ihr könnt Euch seinem Urteil stellen.\n\nPasst gut auf Euch auf, <Fremder/Fremde>. Die toten Könige der Vrykul schätzen es nicht, wenn man sie aus ihrem Schlaf erweckt.", sourceObjective = "Stellt Euch dem Urteil der alten Herrscher der Vrykul.", completion = "Ashildirs Grab wurde geöffnet, Fremder.\n\nWisst Ihr vielleicht etwas darüber?", sourceObjectiveStatus = "unverified-source-field" }
quests[38812] = { id = 38812, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Shadowthrash" }
quests[38813] = { id = 38813, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befehle für die Offiziere", description = "Es bleibt nur noch, Eure Befehle an unsere Hauptmänner der Illidari weiterzuleiten. Die stärksten Truppen der Legion wurden im Vulkan zusammengezogen. Doch dort werden sie nicht lange bleiben.\n\nWir müssen zuerst zuschlagen und zwar so hart wie möglich.\n\nSobald sie vernichtet sind, können wir zum Kommandoschiff hinauffliegen, Brutkönigin Tyranna töten und den Schlüsselstein an uns nehmen. Lord Illidan wird höchst zufrieden sein.", sourceObjective = "Erteilt Euren Illidarioffizieren ihre jeweiligen Einsatzbefehle für den Angriff auf die Brennende Legion im Vulkan.", completion = "Unser Angriff hat begonnen.\n\nSchon bald werden wir siegreich an Lord Illidans Seite im Schwarzen Tempel stehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[38814] = { id = 38814, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Mystical Staff" }
quests[38815] = { id = 38815, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Erweckung der Schildmaid", description = "Jetzt, wo die Rituale unterbrochen und die Knochen zurückgebracht worden sind, können wir vielleicht Ashildir aus den Klauen dieser Knochensprecher befreien.\n\nTief drinnen in Haustvald verfügen die Mystiker über einen besonderen Altar, mit dessen Hilfe Körper und Geist gefallener Krieger wiedervereint werden können. Vielleicht können wir dort Ashildirs Geist mit ihren Knochen zusammenführen und sie so diesen üblen Mystikern entreißen.\n\nGeht jetzt, <Fremder/Fremde>. Ich rufe ihre Wache zusammen.", sourceObjective = "Verwendet die Rune der Erneuerung, um Ashildirs Geist mit ihren Knochen zusammenzuführen.", completion = "Wo... Wo bin ich?\n\nIch... Ich kenne Euch...", sourceObjectiveStatus = "unverified-source-field" }
quests[38816] = { id = 38816, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knochenbrecher der Knochensprecher", description = "Die Verbrechen dieser Ritualisten dürfen nicht ungesühnt bleiben, aber wir können die Strafe nicht vollstrecken. Ihre Runenmagie verleiht ihnen unermessliche Macht über die Toten.\n\nIhr aber seid nicht tot und ich spüre große Kraft in Euch. Bekämpft diese Ketzer und zeigt Ashildir, dass Ihr wahrlich ihres Urteils würdig seid!", sourceObjective = "Besiegt 15 Knochensprechervrykul oder deren Verbündete in Haustvald.", completion = "Euer glorreicher Kampf ehrt die Königin der Valkyra.", sourceObjectiveStatus = "unverified-source-field" }
quests[38817] = { id = 38817, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Royale Reste", description = "Ihr wollt Euch also dem Urteil der Königin der Valkyra stellen? Dann muss es Eure Schuld sein!\n\nDie Knochensprecher von Haustvald haben ein monströses Verbrechen begangen. Sie haben Ashildirs Knochen gestohlen. Sie versuchen damit sicher, Außenseiter davon abzuhalten, die Prüfungen zu bestehen. Das dürft Ihr nicht zulassen!\n\nDringt in Haustvald ein, um ihre Überreste zu bergen. Ich hoffe um Euretwillen, dass Ashildir nachsichtig ist.", sourceObjective = "Sammelt 8 von Ashildirs Knochen in Haustvald.", progress = "Habt Ihr ihre Überreste bergen können?", completion = "Die Verschlagenheit der Knochensprecher kennt keine Grenzen. \n\nDurch ihre Rituale versuchen sie, die Essenz unserer Königin zu verbrennen. Aber wir werden ihre eigene Magie verwenden, um sie zu uns zurückkehren zu lassen!", sourceObjectiveStatus = "unverified-source-field" }
quests[38818] = { id = 38818, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das letzte Urteil", description = "In meinem zerrissenen Zustand habe ich bruchstückhaft erblickt, wie <ein Held/eine Heldin> die verderbten Mystiker von Haustvald bestraft. Jetzt erkenne ich, dass Ihr das wart, {class}.\n\nIch weiß, dass Ihr mein Urteil erwartet, aber mein Geist ist immer noch nicht vereint. Schon jetzt verwendet Runenseher Faljar dunkle, verbotene Magie, um meinen Geist nach Helheim zu verbannen. Wenn es ihm gelingt, ist Eure Prüfung verloren.\n\nMeine Bindung an diesen Ort wird schwächer. Beeilt Euch! Es bleibt nicht mehr viel Zeit!", sourceObjective = "Besiegt Runenseher Faljar in Haustvald.", completion = "Ich kann das alles nicht glauben...\n\nEs tut mir sehr leid, aber ich habe Faljars Macht unterschätzt, Fremder.\n\nIch hätte nie gedacht, dass er uns hier festsetzen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[38819] = { id = 38819, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihre Zahl ist Legion", description = "Ja, diese Verwüster müssen ausgeschaltet werden, doch es gibt noch viel mehr zu tun.\n\nEs steht schlecht, doch wir zählen auf Euch. Die Kommandeure der Brutkönigin kontrollieren den Vulkan, sie müssen sterben. Wir müssen die Legion zerschmettern. Einfach alles, was nötig ist, um den absoluten Sieg zu erringen.", sourceObjective = "Lasst die Untertanen der Brutkönigin und die Brennende Legion in der Gegend um die Infernospitze Euren Zorn spüren.", completion = "Ich stimme absolut zu. Mir scheint, Ihr habt ihre Streitkräfte vollständig ausgelöscht.\n\nWas denkt Ihr? Ist es an der Zeit, zum Kommandoschiff zu fliegen und uns den Sargeritschlüsselstein zu holen?", sourceObjectiveStatus = "unverified-source-field" }
quests[38820] = { id = 38820, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Captain Grok'mar" }
quests[38821] = { id = 38821, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: The Commander's Shield" }
quests[38822] = { id = 38822, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Arcane Wand" }
quests[38823] = { id = 38823, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die bindenden Runen", description = "Auf dieser Steintafel wird ein Ritual beschrieben, mit dem man einen mächtigen Geist in schwächere Teile aufspalten kann, indem man diese an spezielle Runensteine bindet. Offensichtlich will der Runensprecher genau dieses Ritual verwenden, um den Geist von Ashildir zu schwächen.\n\nWenn ihr Geist derart geschwächt ist, könnte es unmöglich werden, sie zu beschwören. Den Ritualen muss Einhalt geboten werden.", sourceObjective = "Zerstört die Ritualsteine, um die Rituale aufzuhalten, die Ashildirs Geist in Haustvald binden.", completion = "Diese Mystiker haben große Anstrengungen unternommen, um Ashildir zu schwächen. \n\nJetzt können wir nur noch hoffen, dass ihr Geist immer noch stark genug ist, um sie erwecken zu können.", sourceObjectiveStatus = "unverified-source-field" }
quests[38825] = { id = 38825, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blazing Crusader" }
quests[38833] = { id = 38833, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kunst des Dämonenstahls", description = "Der Firmamentstein ist einer der wenigen Ambosse auf dieser Welt, der der Wucht der Hammerschläge standhalten kann, die zum Schmieden von Dämonenstahl erforderlich sind.\n\nHier, ich werde es Euch zeigen.\n\nZwei Teile Leystein, ein Teil Teufelsschiefer. Keine Hitze, kein Anlassen, nur reine Kraft und Geschicklichkeit.\n\nVersucht es. Ich werde Euch anleiten.", sourceObjective = "Arbeitet mit Muirn Eisenhorn zusammen, um einen Dämonenstahlbarren herzustellen.", completion = "So, da ist er... Dämonenstahl.\n\nWillkommen auf der nächsten Stufe der Schmiedekunst, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[38834] = { id = 38834, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf ins Getümmel", description = "Die Brennende Legion hat hier einen Sieg errungen, aber die Illidari auch. Anscheinend können die Dämonenjäger dem Ansturm standhalten... wenn auch nur mit Müh und Not.\n\nKommt, setzen wir Eure Waffe sinnvoll ein. Ich werde unsere nächsten Schritte planen, während Ihr die Legion niederkämpft.", sourceObjective = "Sprecht mit dem kommandierenden Dämonenjäger am Verteidigungsposten der Illidari.", completion = "Ihr beide seid ein willkommener Anblick. Wir konnten die Dämonen zwar aus diesen Ruinen vertreiben, aber sie sind stärker als alle, denen wir zuvor begegnet sind.\n\nWir wissen Eure Hilfe zu würdigen. Wenn wir die Invasion der Legion jetzt nicht aufhalten können, werden sie erst Azsuna und dann den Rest der Verheerten Inseln überrennen.", sourceObjectiveStatus = "unverified-source-field" }
quests[38836] = { id = 38836, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aktar's Post" }
quests[38837] = { id = 38837, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Mordvigbjorn" }
quests[38838] = { id = 38838, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Enraged Earthservant" }
quests[38839] = { id = 38839, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Genug gewartet", description = "Mama hat eine Nachricht bekommen und dann gesagt, dass Blut nach Blut ruft. Sie hat gesagt, dass ich hier auf sie warten soll, und ging dann weg. Aber das ist schon zwei Wochen her. Ich mag nicht mehr warten.\n\nIch werde zu Hause bleiben, wenn Ihr sie für mich sucht. Sie sagte, sie wollte zu den Klippen im Süden.", sourceObjective = "Reist zu den südlichen Klippen von Val'sharah und sprecht mit Makra Messerhauch.", sourceObjectiveStatus = "unverified-source-field" }
quests[38840] = { id = 38840, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fischige Angelegenheit", description = "Die Makrura sammeln sich am Strand. Und viel zu viele von ihnen üben sich in Wassermagie.\n\nIch glaube, dass sie eine riesige Welle heraufbeschwören wollen, sobald sie genug Zauberer beisammen haben.", sourceObjective = "Tötet 3 Matschflutwellenrufer an der Südküste von Val'sharah.", sourceObjectiveStatus = "unverified-source-field" }
quests[38841] = { id = 38841, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tod den Fischleuten", description = "Die Makrura sammeln sich am Strand. Und viel zu viele von ihnen üben sich in Wassermagie. Ich glaube, dass sie eine riesige Welle heraufbeschwören wollen.\n\nAußerdem habe ich eine lange Reise hinter mir und keine Vorräte mehr. Ich bin so hungrig, dass ich fast alles essen würde. Sogar die Makrura, die Ihr töten werdet. Aber schneidet ihnen bitte erst die Köpfe ab.", sourceObjective = "Bringt 3 unversehrte Matschflutschwänze zu Makra Messerhauch an den südlichen Klippen von Val'sharah.", sourceObjectiveStatus = "unverified-source-field" }
quests[38842] = { id = 38842, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feenaufruhr" }
quests[38844] = { id = 38844, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rally the Wilds Buff Received" }
quests[38845] = { id = 38845, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungenutzt", description = "<Oronok nimmt Haltung an und richtet sich zu seiner vollen Größe auf.>\n\nIch musste sichergehen, {name}. Und dazu musste ich Euch erst prüfen. Bitte verzeiht meine kleine Maskerade. Ich bin so sehr ein Bauer, wie Ihr <eine Frau/ein Mann> seid, nämlich gar nicht.\n\nWenn Ihr die Litanei der Verdammnis beschaffen wollt, müsst Ihr mir erst zuhören. Wenn Ihr bereit seid, lasst es mich wissen, und ich werde Euch die Geschichte erzählen.", sourceObjective = "Oronok Herzeleid auf Oronoks Hof im Schattenmondtal möchte, dass Ihr Euch seine Geschichte anhört. Sprecht mit Oronok, um ihm zu sagen, dass er mit der Geschichte beginnen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[38847] = { id = 38847, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Berserker" }
quests[38850] = { id = 38850, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fate of Tirion Fordring" }
quests[38857] = { id = 38857, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Gefallen für Herrn Fessel", description = "Throm'ka, {class}. Mein Name ist Seska. Ich bin die Abgesandte einer... Handelsgesellschaft. Wie Ihr sehen könnt, bin ich von diesen Riesen und ihren Nagaverbündeten überwältigt worden.\n\nDrei meiner Gefährten sind während der Untersuchung dieser Höhle ebenfalls gefangen genommen worden. Ich bin mir sicher, dass Herr Fessel, mein Arbeitgeber, sehr dankbar sein würde, wenn Ihr sie befreit.", sourceObjective = "Befreit Spalt Donnerhügel, den sanftmütigen Rosh und Grazia die Grüne.", completion = "Sehr gut, werter Herr. Für die Befreiung meiner Leute kann ich Euch gar nicht genug danken. Und Rosh ist Euch ganz besonders dankbar.\n\n<Der sanftmütige Rosh grunzt.>\n\nVielleicht können wir beide noch weitere Geschäfte machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[38861] = { id = 38861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Val'sharah - Treasure 019 - Lunarwing Shallows - twh" }
quests[38862] = { id = 38862, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diebische Distelblattgeister", description = "Niemand weiß genau, warum die Distelblattgeister die Mondschwingeneier sammeln, aber sie wollen ihnen bestimmt kein warmes Nest bauen.\n\nSaylanna Flussbrise weiß sicher, was mit diesen hier zu tun ist.", sourceObjective = "Sammelt 5 gestohlene Mondschwingeneier am Mondschwingentümpel.", progress = "Sammelt so viele Eier ein, wie Ihr könnt, und bringt sie zurück zu mir. Ich werde sie sicher verwahren.", completion = "Bis ich herausgefunden habe, was diese Distelblattwaldgeister vorhaben, muss ich auf die Mondschwingeneier aufpassen. Zumindest sind sie jetzt in Sicherheit.", sourceObjectiveStatus = "unverified-source-field" }
quests[38863] = { id = 38863, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Partially Mined Apexis Crystal" }
quests[38864] = { id = 38864, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Val'sharah - Treasure 020 - Lunarwing Shallows - twh" }
