quests[38871] = { id = 38871, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst das Blutende Auge bluten" }
quests[38872] = { id = 38872, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl der Dunklen Fürstin", description = "Sind uns diese Kerle freundlich gesinnt? Ist wohl ein gutes Zeichen, dass sie nicht versuchen, Herzogin zu fressen... noch nicht.\n\nWie dem auch sei, ich habe Befehle. Nathanos hat sich den Dunklen Waldläufern angeschlossen, die auf Befehl von Fürstin Sylvanas höchstpersönlich an Bord der Ewigen Vergessenheit eine geheime Mission ausführen! Leider hat die Allianz von unserem Plan erfahren, und jetzt greift Graumähne den Außenposten an!\n\nWir könnten da drüben wirklich Eure Hilfe brauchen, {name}. Herzogin kann Euch dorthinbringen, sagt mir einfach Bescheid.", sourceObjective = "Trefft Euch mit Nathanos Pestrufer am Schreckensflutufer.", completion = "Endlich trifft mal jemand mit Sachverstand an diesem jämmerlichen Außenposten ein. \n\nUnsere Bemühungen, Sylvanas' Mission durchzuführen, sind zum Stillstand gekommen. Aber jetzt gibt es sogar noch dringendere Probleme.", sourceObjectiveStatus = "unverified-source-field" }
quests[38873] = { id = 38873, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Macht das Deck klar!", description = "Unsere Mission in Skold-Ashil muss vorerst warten, {class}. Jetzt gibt es dringendere Angelegenheiten, um die wir uns kümmern müssen.\n\nIch bin erst vor Kurzem mit Verstärkung hier eingetroffen, als Graumähnes Schiff auftauchte und die Mauern unter Beschuss nahm. Wir haben unsere Belagerungswaffen kampfbereit gemacht, aber ihre Bodentruppen haben uns blitzschnell überwältigt.\n\nWenn Ihr an die Katapulte rankommt und auch noch die Männer an den Kanonen ausschalten könnt, verschafft uns das vielleicht genug Zeit, den Angriff zurückzuschlagen!", sourceObjective = "Feuert 4 Katapulte der Verlassenen bei Graumähnes Sturm ab.", completion = "Ha! Graumähne wird keine Freude an seinen Kanonen mehr haben, wenn die Pest seine Leute ausschaltet!", sourceObjectiveStatus = "unverified-source-field" }
quests[38876] = { id = 38876, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf die Dämonenschmiede", description = "Die Eiserne Horde schafft ununterbrochen neue Verstärkungen aus ganz Draenor heran, um ihre Position bei der Höllenfeuerzitadelle zu festigen. Wenn es uns nicht gelingt, ihnen den Nachschub abzuschneiden, geraten unsere Pläne in Tanaan in Gefahr.\n\nJetzt ist ein strategischer Angriff auf die Nachschublinien im Eisenfausthafen die erste Wahl, um die Eiserne Horde weiter in die Defensive zu drängen und selbst die Kontrolle zu wahren.", sourceObjective = "Greift die Nachschubeinheiten der Eisernen Horde im Eisenfausthafen im Tanaandschungel an.", sourceObjectiveStatus = "unverified-source-field" }
quests[38877] = { id = 38877, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf die Dämonenschmiede", description = "Die Eiserne Horde schafft ununterbrochen neue Verstärkungen aus ganz Draenor heran, um ihre Position bei der Höllenfeuerzitadelle zu festigen. Wenn es uns nicht gelingt, ihnen den Nachschub abzuschneiden, geraten unsere Pläne in Tanaan in Gefahr.\n\nJetzt ist ein strategischer Angriff auf die Nachschublinien im Eisenfausthafen die erste Wahl, um die Eiserne Horde weiter in die Defensive zu drängen und selbst die Kontrolle zu wahren.", sourceObjective = "Greift die Nachschubeinheiten der Eisernen Horde im Eisenfausthafen im Tanaandschungel an.", sourceObjectiveStatus = "unverified-source-field" }
quests[38878] = { id = 38878, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schildgeheimnisse", description = "Unser Ziel liegt im Innern dieser Kammer, {class}. Jetzt ist keine Zeit, es in allen Einzelheiten zu erzählen. Ihr müsst nur wissen, dass es von höchster Bedeutung für die Verlassenen ist, dass wir erfolgreich sind.\n\nDie Schildmaiden haben bis jetzt erbitterten Widerstand geleistet, aber ich glaube, es gibt noch einen anderen Weg hinein. Einige wenige ihres Ordens haben dort Zutritt, und ich möchte, dass Ihr herausfindet, wie sie das machen.\n\nIn der Stadt habe ich auffällig gravierte Schilde gesehen, die ihnen wohl von den Champions überreicht werden. Die darauf gezeigten Szenen könnten der Schlüssel zur Kammer sein.", sourceObjective = "Untersucht 6 gravierte Vrykulschilde in Skold-Ashil.", completion = "Ich hoffe, dass Ihr gute Neuigkeiten für mich habt, {class}.\n\nDas wäre in unser beider Interesse.", sourceObjectiveStatus = "unverified-source-field" }
quests[38882] = { id = 38882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein neues Leben für die Untoten", description = "Ihr scheint voller Überraschungen zu stecken, {name}. Mit dem Segen der Königin der Valkyra ist es Euch gelungen, einen Pfad zu öffnen, der das Schicksal von ganz Azeroth beeinflussen wird.\n\nWerdet Zeuge der Geburt eines neuen Zeitalters der Verlassenen!", sourceObjective = "Folgt Sylvanas in die Kammer von Eyir.", completion = "Wir scheinen Graumähnes Hartnäckigkeit unterschätzt zu haben. Dieser Fehler kommt die Verlassenen teuer zu stehen.\n\nAber diese Eyir kann sich nicht ewig verstecken. Wenn es sein muss, jage ich sie durch die Hallen der Tapferkeit und zurück!\n\nGeht jetzt, {class}. Ich lasse Euch rufen, wenn ich Euch brauche.", sourceObjectiveStatus = "unverified-source-field" }
quests[38885] = { id = 38885, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shivering Ashmaw Cub" }
quests[38886] = { id = 38886, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Val'sharah - Treasure 021 - Sleeper's Barrow - twh" }
quests[38887] = { id = 38887, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Val'sharah - Bluffs - Vignette: Swiftflight - TRACKING - twh" }
quests[38888] = { id = 38888, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hochbergtauren", description = "Ihr habt mir ein paar interessante Steine mitgebracht, {name}. Ich habe einen besonderen Auftrag für Euch, falls Ihr interessiert seid.\n\nIch habe Geschichten über diese Tauren auf dem Hochberg gehört. Sie behaupten von sich selbst, Meister des Bergbaus zu sein. Ich weiß nicht, ob sie so viel Talent wie wir beide haben, aber sie bauen Leystein schon weitaus länger ab.\n\nSucht sie doch auf und hört Euch an, was sie zu erzählen haben.", sourceObjective = "Meldet Euch bei Ronos Eisenhorn auf dem Hochberg.", completion = "Ihr seid in der Tat ein Bergarbeiter. Ich kann es Euch ansehen: Ihr habt Erz im Blut.", sourceObjectiveStatus = "unverified-source-field" }
quests[38889] = { id = 38889, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zur Adoption freigegeben", sourceObjective = "Ihr kniet nieder und streckt eine Hand aus. Das Bärenbaby schnüffelt an Euren Fingern und schaut Euch vertrauensvoll an.\n\nDas Junge ist zu klein, um für sich selbst zu sorgen. Werdet Ihr es mit auf Eure Reisen nehmen?", sourceObjectiveStatus = "unverified-source-field" }
quests[38893] = { id = 38893, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Val'sharah - Treasure 022 - Whispering Bluffs - twh" }
quests[38894] = { id = 38894, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegründete Garnison" }
quests[38895] = { id = 38895, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Val'sharah - Vignette: Swiftflight - Treasure001 - twh" }
quests[38900] = { id = 38900, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Val'sharah - Bluffs - Vignette: Nightcaller - TRACKING - twh" }
quests[38901] = { id = 38901, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Teufelsschmiedemeister", description = "Ihr kommt gut mit diesem Teufelsschiefer zurecht, <mein Junge/meine Liebe>. Ich sollte Euch zu jemandem schicken, der sich damit besser auskennt als ich.\n\nDie Illidari haben eine Vorliebe für diesen Dämonenkram und es soll ein paar Bergarbeiter geben, die unweit der Dämonen in Suramar ihre Zelte aufgeschlagen haben.\n\nSucht sie auf und findet heraus, was sie Euch beibringen können.", sourceObjective = "Sucht Teufelsschmiedin Nal'ryssa in Suramar auf.", completion = "Ihr wollt Teufelsschiefer abbauen?\n\nTraut Ihr Euch das wirklich zu?\n\nSeid Ihr bereit, Opfer zu bringen?\n\nGut.", sourceObjectiveStatus = "unverified-source-field" }
quests[38902] = { id = 38902, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Coruscating Bloom" }
quests[38903] = { id = 38903, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Val'sharah - Bluffs - Vignette: Nightcaller - Interaction - TRACKING - twh" }
quests[38904] = { id = 38904, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zur Verheerten Küste", description = "Keine Sorge, {name}. Ich bin zwar verärgert, aber ich werde nicht blindlings in den Tod rennen.\n\nWir fliegen hinein und spähen den idealen Angriffspunkt aus. Die Dämonen sind immer noch siegestrunken, aber wir werden ihrer Feierlaune ein schnelles Ende bereiten!\n\nNehmt mein Ersatzreittier und wir fliegen zur Verheerten Küste. Dort werden wir unseren Toten alle Ehre bereiten.", sourceObjective = "Nehmt Saurfangs Ersatzreittier, begebt Euch zur Verheerten Küste und kämpft dort zur Wiederherstellung Eurer Ehre an seiner Seite.", completion = "Willkommen in der Himmelsfeste. Für gewöhnlich erhalten nur die Toten Zutritt, doch die Zeiten ändern sich.", sourceObjectiveStatus = "unverified-source-field" }
quests[38907] = { id = 38907, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hüter des Hammers", description = "Die Hochbergstämme hatten vor, Euren Streitkräften unsere Hilfe zuzusichern, denn wir wissen, dass der Krieg mit der Brennenden Legion vor uns liegt.\n\nWir kämpfen jedoch gegen Verrat aus den eigenen Reihen und müssen nun Euch um Unterstützung bitten.\n\nEin wichtiges Relikt, der Hammer von Khaz'goroth, wurde meinen Leuten von den niederträchtigen Drogbar gestohlen.\n\nWir benötigen Eure Hilfe, um ihn zurückzuerobern.", sourceObjective = "Trefft Euch mit Mayla Hochberg in Donnertotem am Hochberg.", completion = "Ich weiß, Ihr sucht die Säule der Schöpfung, aber ich muss Euch leider mitteilen, dass sie eins der vielen Dinge war, die wir heute verloren haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[38909] = { id = 38909, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hoch hinaus", description = "Es ist kein Zufall, dass die Flussmähnen von Dargrul so vehement angegriffen wurden. Ihre Bauernhöfe und Weiden liefern die Nahrung für diese Region.\n\nBitte bringt Jale nach Donnertotem. Mit ein wenig Glück hat Mayla Verstärkung zur Verfügung, die sie hierher entsenden kann.\n\nWir werden die Überlebenden hier zusammenrufen und dann so schnell wie möglich nachkommen.", sourceObjective = "Bringt Jale Flussmähne nach Donnertotem.", progress = "Hattet Ihr Erfolg bei den Flussmähnen?", completion = "Die Flusswindung ist zerstört worden...? Dargrul, diese widerwärtige Bestie! Ich werde ihn so lange jagen, bis er tot ist.\n\nAber allein mit unseren Truppen wird uns das nicht gelingen.\n\nWir brauchen die Hilfe der anderen Stämme.", sourceObjectiveStatus = "unverified-source-field" }
quests[38910] = { id = 38910, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rocs gegen Adler", description = "Die Großschwester der Scharrfurien hat ihre Hexen gelehrt, wie man unsere geliebten Adler verflucht und in widerwärtige Rocs verwandelt, die das Tal angreifen, wie Ihr selbst sehen könnt.\n\nEs gibt keine Möglichkeit, diesen Fluch aufzuheben, wenn er sich erst einmal festgesetzt hat.\n\nWir werden uns in die Lüfte schwingen und gegen die Rocs kämpfen, aber wir benötigen Eure Hilfe am Boden.\n\nBegebt Euch durch das Dunkelfedertal nach Norden und lasst alle Adler frei, die Ihr finden könnt.\n\nJeder Adler, den Ihr rettet, ist ein Roc weniger, den wir später töten müssen.", sourceObjective = "Rettet 7 gefangene große Adler.", completion = "Eure Tapferkeit hat uns einige unserer großartigen gefiederten Freunde zurückgebracht. Gut gemacht.\n\nWie wäre es jetzt mit einem Frontalangriff?", sourceObjectiveStatus = "unverified-source-field" }
quests[38911] = { id = 38911, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Stamm der Flussmähnen", description = "Die Zeit reicht nicht aus, alles zu erzählen, was hier geschehen ist. Kurz gesagt haben unsere Stämme sich nach dem Angriff, bei dem der Hammer von Khaz'goroth in die Hände der barbarischen Drogbar fiel, in alle Winde zerstreut.\n\nDie Drogbar greifen den Stamm der Flussmähnen noch immer an, und ich habe nicht genug Krieger, um ihnen Hilfe zu schicken.\n\nWir brauchen <einen Helden/eine Heldin> wie Euch. Bitte begebt Euch zur Gabe der Erdenmutter und eilt ihnen zu Hilfe.", sourceObjective = "Trefft Jale Flussmähne bei der Gabe der Erdenmutter.", completion = "Mayla hatte tatsächlich jemanden, der uns helfen kann? Ich könnte das Kind umarmen.\n\nWillkommen, Fremder. Ich bin Jale Flussmähne, Häuptling des Stammes der Flussmähnen. Und wir könnten Eure Hilfe wahrlich brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[38912] = { id = 38912, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Stamm der Bluttotems", description = "Der Bluttotemstamm wird von Torok angeführt, einem etwas launischen, aber kompetenten Taurenhäuptling. Er ist Fremden gegenüber misstrauisch, aber ich glaube, Ihr habt bereits seinen Abgesandten Oakin Eisenstier kennengelernt, als Ihr ihn an der Flusswindung gerettet habt.\n\nVielleicht könnt Ihr diesen kleinen Gefallen erwähnen und so die Bluttotems als Verbündete zurückgewinnen. Der Hochbergstamm braucht sie, um die Drogbar zu besiegen und den Hammer von Khaz'goroth zurückzubeschaffen. Passt auf Euch auf, {name}.", sourceObjective = "Trefft Euch mit Oakin Eisenstier am Klippenrand.", completion = "Ihr seid einer der wenigen Fremdlinge von außerhalb des Hochbergs, der es lebend bis in diese Wälder geschafft hat. Da ich für Euch gebürgt habe, erhielt der Bluttotemstamm von Torok den Befehl, Euch nicht zu töten.", sourceObjectiveStatus = "unverified-source-field" }
quests[38913] = { id = 38913, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Stamm der Himmelshörner", sourceObjective = "Trefft Euch mit Lasan Himmelshorn am Himmelshorn.", completion = "Ha ha! Was seid Ihr denn für ein Winzling? Seid Ihr hier, um mit oder gegen uns zu kämpfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[38915] = { id = 38915, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht um die Schneeblinde Hochebene", description = "Ihr kommt gerade zur rechten Zeit. Unsere Streitkräfte in der Schneeblinden Hochebene melden, dass sie den Unterkönig an der Oberfläche gesehen haben.\n\nDarüber hinaus ist er wohl nur leicht bewacht und trägt den Hammer bei sich. Dank Eurer Bemühungen können wir ihm nun im Kampf entgegentreten.\n\nTrefft Euch mit uns an der Schneeblinden Hochebene und lasst uns Dargrul zusammen bekämpfen.", sourceObjective = "Reist zur Schneeblinden Hochebene.", completion = "Das sind... eine Menge Drogbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[38916] = { id = 38916, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse des Hochbergs", description = "Maylas Vater Ulan war unser letzter Oberhäuptling. Er wurde getötet, als er den Unterkönig davon abhalten wollte, den Hammer von Khaz'goroth zu ergreifen.\n\nIch habe Mayla schon ihr ganzes Leben lang beobachtet und weiß deshalb, dass sie genug Tapferkeit und Stärke besitzt, um die Rolle des Oberhäuptlings zu übernehmen.\n\nWir müssen nur dafür sorgen, dass sie dies selbst erkennt.\n\nWürdet Ihr uns am Stadteingang entlang der südlichen Klippen treffen? Es gibt ein Ritual, das helfen kann, doch um es zu überleben, bräuchten wir Eure Hilfe.", sourceObjective = "Trefft Geistwandler Ebenhorn an der südlichen Klippe von Donnertotem.", completion = "Ah, danke, dass Ihr gekommen seid. Mayla ist genauso stur wie ihr Vater, wenn nicht noch sturer.", sourceObjectiveStatus = "unverified-source-field" }
quests[38922] = { id = 38922, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jungflaum", description = "Bitte helft mir, <Fremder/Fremde>! Meine einst so friedlichen Brüder und Schwestern sind in zornige Raserei verfallen.\n\nMein Neffe und ich haben versucht, den Stamm gegen den Willen des Häuptlings zu verlassen, woraufhin sie ihn mir weggenommen haben und mich fast zerrissen hätten, wenn ich nicht geflohen wäre.\n\nEr wird noch im Dorf gefangen gehalten und ich befürchte das Schlimmste.\n\n{class}, ich flehe Euch an: Rettet ihn! Ich bin zu alt und zu schwach, um diese Aufgabe selbst zu bewältigen.", sourceObjective = "Sprecht mit Jungflaum im Schwelhautdickicht.", completion = "Onkel?", sourceObjectiveStatus = "unverified-source-field" }
quests[38923] = { id = 38923, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorherrschaft in Ashran", description = "Die Allianz weigert sich, in Ashran nachzugeben. Zeigt ihr, dass die Horde nicht einfach tatenlos zusieht, während sie die Macht des alten Ogerreichs für ihre Zwecke an sich reißt.", sourceObjective = "Besiegt die gegnerische Fraktion an den Ereignisstandorten in Ashran und tötet den Anführer in ihrer Basis.", sourceObjectiveStatus = "unverified-source-field" }
quests[38924] = { id = 38924, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Continue the Domination" }
quests[38925] = { id = 38925, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorherrschaft in Ashran", description = "Wie wir schon befürchtet haben, versucht die Horde mit Raubzügen ihre Stellung hier auf der Insel zu festigen. Zieht hinaus und zeigt ihnen, dass die Allianz sich derartige Überfälle nicht gefallen lässt.", sourceObjective = "Besiegt die gegnerische Fraktion an den Ereignisstandorten in Ashran und tötet den Anführer in ihrer Basis.", sourceObjectiveStatus = "unverified-source-field" }
quests[38926] = { id = 38926, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haltet die Vorherrschaft", description = "Wie wir schon befürchtet haben, versucht die Horde, mit Raubzügen ihre Stellung hier auf der Insel zu festigen. Zieht hinaus und zeigt ihnen, dass die Allianz sich derartige Überfälle nicht gefallen lässt.", sourceObjective = "Besiegt die Horde an allen Ereignisstandorten in Ashran und liquidiert den Obersten Kriegsfürsten Volrath.", sourceObjectiveStatus = "unverified-source-field" }
quests[38927] = { id = 38927, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampfgestählt", description = "Besiegt Eure Gegner auf dem Schlachtfeld und ihr werdet belohnt werden.", sourceObjective = "Gewinnt 3 gewertete Schlachtfelder.", sourceObjectiveStatus = "unverified-source-field" }
quests[38929] = { id = 38929, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampfgestählt", description = "Besiegt Eure Gegner auf dem Schlachtfeld und ihr werdet belohnt werden.", sourceObjective = "Gewinnt 3 gewertete Schlachtfelder.", sourceObjectiveStatus = "unverified-source-field" }
quests[38932] = { id = 38932, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausstattungsbaupläne: Bilgenpumpe", description = "Das scheinen Baupläne für Schiffsausrüstung zu sein. Wir sollten sie zu unserer Schiffswerft zurückbringen, um zu sehen, ob sie jemand entziffern kann.", sourceObjective = "Bringt die Pläne zu einem Spezialisten für Marineausstattung in der Werft Eurer Garnison.", progress = "Das sieht mir nach Ausstattungsbauplänen aus!", completion = "Das ist der Bauplan für eine hochmoderne Schiffsausstattung. Anhand dieser Pläne sollte ich die Ausrüstung nachkonstruieren können, sie wird schon bald für Euch bereit sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[38933] = { id = 38933, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Logistische Angelegenheiten", description = "Ich denke, wir sind bereit, der Legion auf den Verheerten Inseln erneut unsere Aufwartung zu machen.\n\nLord Grayson Schattenbruch hat sich freiwillig gemeldet, unsere Bodenstreitkräfte zu koordinieren. Ihr solltet gleich mit ihm sprechen, Hochlord.", sourceObjective = "Sprecht mit Lord Grayson Schattenbruch.", completion = "Es ist an der Zeit für einen Gegenangriff auf die Legion.", sourceObjectiveStatus = "unverified-source-field" }
quests[38934] = { id = 38934, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Silas' Geheimversteck", description = "Einen großen Dunkelmond-Schatz Ihr sucht, doch seid gewarnt, vielleicht ist er verflucht!\n\nDer erste Hinweis zum sicheren Siegen, steht auf der Rückseite dieses Schriftstücks geschrieben.", sourceObjective = "Findet Silas' Geheimversteck.", sourceObjectiveStatus = "unverified-source-field" }
quests[38935] = { id = 38935, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sein Name war Sturmbräu", description = "Im Land gehen Gerüchte über einen ungewöhnlichen Pandarenmönch um, dessen Mächte lediglich durch seinen Durst für Gebräu übertroffen werden.\n\nEr war auf der Durchreise, gemeinsam mit seiner kleinen Nichte, deren große Klappe ihnen einiges an Ärger einzubringen scheint.\n\nDie Einheimischen sagen, die beiden wären auf dem Weg zum Tal der Vier Winde. Ihr solltet ihn kennenlernen! Doch... hütet Euch vor seinem rechten Haken.", sourceObjective = "Sprecht mit Chen Sturmbräu auf den Donnerfußfeldern im Tal der Vier Winde.", completion = "Ha ha! Bolo hat Euch geschickt? Der \"Fassflüsterer\", stimmt's? Aus dem Betrunkenen Ho-zen?\n\nWie geht es seinem Auge? Und ist sein Freund immer noch verkatert?\n\nAch, das war mal ein schöner Abend.", sourceObjectiveStatus = "unverified-source-field" }
quests[38936] = { id = 38936, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Straße nach Kun-Lai", description = "Lehrensucher Cho hat uns berichtet, dass mehrere Eurer Gefährten den Konflikt im Jadewald überstanden haben und zur Heilung zum Kun-Lai-Gipfel gebracht wurden.\n\nSie werden nur mit Eurer Hilfe überleben!\n\nUm den Kun-Lai-Gipfel zu erreichen, müsst Ihr Euch ins Tal der Vier Winde begeben und nach den reisenden Grummeln des Höhenpfads suchen, die sich am Fuße der Verhüllten Treppe entlang der nordöstlichen Grenze befinden.\n\nSie können Euch den Rest des Weges führen.", sourceObjective = "Reist über die Verhüllte Treppe nach Binan.", completion = "Oh, Ihr seid ein Freund von Cho? Willkommen! Willkommen!\n\nIch würde Euch ein Bankett auftischen, aber wie Ihr sehen könnt, stecken wir momentan in großen Schwierigkeiten.\n\nWürdet Ihr uns vielleicht helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[38938] = { id = 38938, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bärenschicksal", description = "Nicht weit von hier scheint ein Bärenjunges in Not zu sein. Wollt Ihr Euch die Sache vielleicht anschauen?", sourceObjective = "Schaut Euch das zitternde Aschenmauljunge im südlichen Val'sharah an.", sourceObjectiveStatus = "unverified-source-field" }
quests[38939] = { id = 38939, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf Skold-Ashil" }
quests[38940] = { id = 38940, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "First Mission Complete" }
quests[38943] = { id = 38943, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Val'sharah - Treasure 023 - Moonclaw Vale - twh" }
quests[38944] = { id = 38944, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Am Anfang war der Stoff", description = "Jedes Mal, wenn uns Dalaran in neue Länder führt, bin ich gespannt, welche neuen Stoffe und Tücher wir dort entdecken werden.\n\nMit Magie durchwirkte Fäden? Dämonisch angehauchte Textilien?\n\nOh, ich hoffe, es sind nicht wieder FELLE.\n\nIhr seid <ein Abenteurer/eine Abenteurerin> und <ein Schneider/eine Schneiderin>. Macht Euch auf den Weg nach unten und bringt uns ein paar schöne Sachen mit!", sourceObjective = "Beschafft 10 Stücke Shal'doreiseide. Shal'doreiseide bekommt Ihr von Humanoiden auf den Verheerten Inseln, von anderen Abenteurern oder über einen Ankauf im Auktionshaus.", progress = "Ich hätte nichts dagegen, mit Kaschmirwolle zu arbeiten...", completion = "Also damit... damit kann ich etwas anfangen!\n\nDas erinnert mich an einen alten nachtelfischen Stoff für Festgewänder, den ich mal gesehen habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[38945] = { id = 38945, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ganz einfache Sache... oder?", description = "Ich habe jede Menge Seidenmuster, die sich für diesen Stoff eignen würden.\n\nHelft mir bei der Vorbereitung der Materialien, {name}. Wir werden einen guten Nutzen für diesen Stoff finden, indem wir eine neue Robe für Euch herstellen.", sourceObjective = "Stellt eine handgefertigte seidengewebte Robe auf Tanithrias Sticktischchen her. Das dazu erforderliche Muster findet Ihr in Eurer Schnittmusterliste. Die dazu erforderlichen Materialien findet Ihr in ihrem Laden.", completion = "Was für eine Schande. Ohne die Möglichkeit, ihn zu nähen, können wir kaum etwas Gescheites mit diesem Stoff anfangen.\n\n<Tanithria schmollt.>\n\nAber immerhin kennen wir ein paar Muster, die auch OHNE Nähte funktionieren. Schulterpolster sind leicht und Gürtel sogar ein Kinderspiel.", sourceObjectiveStatus = "unverified-source-field" }
quests[38946] = { id = 38946, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rat von den Einheimischen", description = "Wer auch immer diesen Stoff gewebt hat, wird ihn ganz sicher nicht nur für Schulterpolster und Gürtel vorgesehen haben. Es muss einen Weg geben, wie man diesen Stoff mit Fäden vernähen kann.\n\nBegebt Euch runter nach Azsuna und sucht dort nach einem Schneider. Wenn wir richtig schneidern wollen, müssen wir nähen können.", sourceObjective = "Sucht einen Schneider in Azsuna.", completion = "Was für ein Anblick! So ein junger, attraktiver {class} in magischer Kluft. Was verschafft mir denn diese Ehre?\n\nAha! Die Schneiderei! Heute ist Euer Glückstag... äh...\n\nPardon, wie war gleich Euer Name? {name}?\n\nHeute ist Euer Glückstag, {name}! Ich bin nämlich einer der besten Schneider in Suramar...", sourceObjectiveStatus = "unverified-source-field" }
quests[38947] = { id = 38947, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runenfaden aus Katgut", description = "Lasst mich raten... Probleme mit dem Faden? Aha.\nHabe ich mir gedacht. Mein Volk webt prächtige Seide, aber sie ist sehr speziell und man kann sie nicht mit jeder Art Faden nähen.\n\nIn Shal'doreiseide wird ein bisschen Leyenergie mit eingewoben. Ihr benötigt also etwas, das an die Leyenergien in diesem Land angepasst ist.\n\nIch rede von Eulenkatzen, <mein Freund/meine Liebe>! Sie haben, was Ihr braucht. Ihr findet sie in den Ruinen von Llothien.", sourceObjective = "Besorgt 3 Runenfäden aus Katgut.", progress = "Das sind wirklich bemerkenswerte Tiere. Ich hatte mal einen als Haus- und Reittier... Das ist aber schon eine Ewigkeit her.", completion = "Perfekt. Wundervoll!", sourceObjectiveStatus = "unverified-source-field" }
quests[38948] = { id = 38948, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harte Zeiten", description = "Als ich noch bei der Schneidergilde in Suramar tätig war, standen mir immer Muster zur Verfügung, nach denen ich arbeiten konnte.\n\nLeider und zu meiner großen Schande habe ich dann im Verlauf einer Pechsträhne all meine Muster verloren.\n\nAllerdings verfügen die Nagazauberinnen in der Lagune im Westen über ausgezeichnet gearbeitete Gelenkbänder. Und die Nachtsüchtigen im Norden tragen Roben, die wir auch verwenden können. Vielleicht könnt Ihr ihren gierigen Klauen ja welche entreißen...", sourceObjective = "Besorgt eine fleckige Seidenrobe und ein Paar Gelenkbänder der Hassnattern.", progress = "Was habt Ihr denn da?", completion = "{name}, Ihr verfügt über wirklich erstaunliche Fähigkeiten. Ich bitte Euch, Muster zu besorgen, und Ihr erledigt das, ohne weitere Fragen zu stellen. Bemerkenswert!", sourceObjectiveStatus = "unverified-source-field" }
quests[38949] = { id = 38949, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Und Ihr wollt nähen können?", description = "Sehr gut. Ich glaube, wir können anfangen.\n\n<Lyndras wirft einen verstohlenen Blick auf Eure mächtige Waffe. In seinem Gesicht zeichnet sich Gier ab, bevor er sich wieder zusammenreißen kann.>\n\nLasst uns die Materialien vorbereiten und dann die Robe und die Armschienen herstellen, die Ihr Euch so sehr verdient habt.", sourceObjective = "Stellt eine runenbestickte seidengewebte Robe und ein Paar runenbestickte seidengewebte Armschienen an Lyndras' Sticktischchen her. Die dazu erforderlichen Muster findet Ihr in Eurer Schnittmusterliste.", progress = "Ihr könnt von Glück reden, mich gefunden zu haben.", completion = "So, fertig!\n\nNein, Ihr müsst mir nicht danken. Ich freue mich, dass ich Euch helfen konnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[38950] = { id = 38950, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der eigenwillige Schneider", description = "Dürfte ich Euch um einen Gefallen bitten, {name}?\n\nDa ich ja zurzeit kein Zuhause, keinen Laden, keine Familie und keine Freunde habe, habe ich mich gefragt, ob Ihr mir nicht Eure schwebende Stadt zeigen könnt. Ich muss gestehen, dass ich SEHR neugierig auf diesen Ort bin. Und außerdem habe ich nur Gutes über die Schneiderei dort gehört.\n\nIch selbst wüsste nicht, wie ich dort hinkommen soll, aber in solch einer magischen Stadt MUSS es doch jemanden geben, der mich dort hineinbeschwören kann?\n\n<Lyndras schaut Euch hoffnungsvoll an.>", sourceObjective = "Sprecht mit Lalla Hellzwirn in Dalaran und bittet sie, Lyndras herbeizubeschwören.", completion = "Euer Freund ist gewiss... eine interessante Erscheinung.\n\nUnd er hat Euch das Nähen dieser Seide gelehrt? Hm... Vielleicht sollten wir ihn eine Weile hierbehalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[38951] = { id = 38951, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nadel gesucht", description = "In diesem Laden gibt es fast alles, was wir brauchen. Leider ist die Qualität der Nähnadeln nicht ganz zufriedenstellend.\n\nAber ich weiß, wo wir bessere Nadeln bekommen. Die Waldgeister von Val'sharah sind über und über bedeckt mit Dornen, die sich glücklicherweise perfekt als Nähnadeln eignen.\n\nSich an ihnen zu stechen ist zwar mehr als unangenehm, aber sie würden hier wirklich einen gewaltigen Unterschied machen.", sourceObjective = "Besorgt 150 Waldgeistdornen.", progress = "Euer Freund glaubt, dass es mit diesen Nadeln besser geht?", completion = "Hm... Er könnte vielleicht recht haben.\n\nDiese Nadeln sind wirklich SEHR stark und trotzdem biegsam. Aber mit der Form und Handhabung bin ich nicht einverstanden. Ich habe da eine Idee...", sourceObjectiveStatus = "unverified-source-field" }
quests[38952] = { id = 38952, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pingelige Präzision", description = "Die Nadeln sind spitz, aber seht sie Euch genau an. Einige sind gebogen, bei anderen hängen kleine Sporne an der Seite. Schaut Euch diese an... sie weist einen rechten Winkel auf! Ich habe nicht vor, um die Ecke zu nähen.\n\nTiffany Cartier im Juwelierladen hat für sowas ein gutes Auge. Bringt ihr diese Nadeln, dann wird sie sie richten.", sourceObjective = "Bringt die Waldgeistdornen zu Tiffany Cartier in Dalaran.", progress = "Was ist das, {name}?", completion = "Seht sie Euch an! Stark, leicht, biegsam, spitz mit einer raffinierten Biegung und glatten Kanten. Da habt Ihr mit Sicherheit einen Hauch von Dalaran ins Spiel gebracht. Jetzt hat sie das Beste aus beiden Welten!\n\nGenug Aufhebens wegen unserer Werkzeuge. Wollen wir nähen?", sourceObjectiveStatus = "unverified-source-field" }
quests[38953] = { id = 38953, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fortgeschrittene Nadelarbeit", description = "Ihr habt schon die Muster für Armschienen, Gürtel, Schulterklappen und natürlich die Robe erlernt. Aber leider habt Ihr zu viel Material verschwendet... Ihr braucht eine bessere Technik.\n\nUnd dafür brauchen wir diese Nadeln.\n\nHier, ich zeige Euch, wie man die Arbeitsprozesse dieser Muster verbessert.", sourceObjective = "Stellt eine bestickte seidengewebte Robe auf Tanithrias Sticktischchen her. Die dazu erforderlichen Materialien findet Ihr in ihrem Laden.", progress = "Konzentriert Euch ganz auf Eure Nadelarbeit. Jetzt nicht nachlässig werden!", completion = "Ist das nicht wundervoll? Und jetzt versucht es selbst!", sourceObjectiveStatus = "unverified-source-field" }
quests[38954] = { id = 38954, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo ist Lyndras hin?", description = "Seltsam... Lyndras war gerade noch hier und ist dann einfach weggelaufen. Und er hatte so einen komischen Gesichtsausdruck.\n\nVielleicht sollten wir nach ihm suchen.", sourceObjective = "Sucht Lyndras.", completion = "Tut mir leid, {name}. Ihr habt mich beim Rumschnüffeln ertappt. Die Neugier hat mich einfach übermannt.\n\nBitte lasst es mich wiedergutmachen.", sourceObjectiveStatus = "unverified-source-field" }
quests[38955] = { id = 38955, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tolle Tasche", description = "Eure Schneiderfertigkeiten sind recht beeindruckend. Und auch wenn ich meine Muster verloren habe, kenne ich noch ein paar von ihnen auswendig... darunter auch eines für eine einfache Tasche.\n\nMacht es mir nach, {name}.", sourceObjective = "Stellt eine handgefertigte seidengewebte Tasche her. Die dazu erforderlichen Materialien findet Ihr in der Schneiderei von Dalaran.", progress = "Es gibt doch nichts Schöneres als eine neue Tasche.", completion = "So, da ist sie. Nicht die beste Tasche der Welt, aber trotzdem besser als die meisten.\n\nEs tut mir immer noch leid, dass ich einfach weggelaufen bin, {name}. Ich werde manchmal von meiner Gier... äh... meiner Neugier... übermannt. Ich verspreche, dass es nicht wieder vorkommen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[38956] = { id = 38956, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo ist Lyndras jetzt hin?", description = "Oh je.\n\nEr hatte Euch gerade erst versprochen, dass er nicht wieder weglaufen würde, und jetzt ist er schon wieder verschwunden!\n\nIch glaube langsam, dieser Lyndras ist etwas zu launenhaft für meinen Geschmack.\n\nBitte findet ihn, bevor er in Schwierigkeiten gerät.", sourceObjective = "Sucht nach Lyndras in Dalaran.", completion = "Bitte nehmt meine aufrichtige Entschuldigung an, {name}. Ich habe nicht nur mich zum Narren gemacht, sondern auch den guten Ruf Eurer Schneiderei gefährdet.\n\nIhr habt allen Grund, wütend auf mich zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[38957] = { id = 38957, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst Euch inspirieren", description = "Ich wünschte, ich könnte Euch weitere Muster überlassen, aber mein Notizbuch ist zusammen mit meinem Laden verloren gegangen. Wir müssen uns ein paar eigene Muster ausdenken.\n\nIch habe über die ledernen Bundhosen der Vrykul aus Sturmheim nachgedacht. Sie sind viel dicker und stärker als alles, was wir nähen könnten, aber die Runendekorationen darauf sind sehr beeindruckend.\n\nWenn ich ein paar davon hätte, könnte ich diese Runen vielleicht auf etwas... feinere... Stoffe übertragen.", sourceObjective = "Beschafft 6 runenverzierte Bundhosen.", progress = "Ich freue mich schon darauf.", completion = "Aha! Das wird noch leichter, als ich zunächst gedacht hatte.\n\n<Lyndras kritzelt hastig ein paar Anleitungen auf ein Stück Pergament.>\n\nHier, {name}. Das ist für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[38958] = { id = 38958, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die richtige Farbe", description = "Dürfte ich kurz um Eure Hilfe bitten, {name}?\n\nIch versuche mich gerade an der Nachbildung eines Schuhwerkmusters, das ich vor einer Weile gesehen habe. Aber ich habe Probleme, mit meinen Farbstoffen den richtigen Farbton hinzubekommen. Das Schwarz ist zu dunkel, das Blau zu hell, und wenn man sie mischt, sieht es auch nicht richtig aus.\n\nDie Farbe, die ich suche, ist eher eine Art Tintenfischblau. Könntet Ihr mir so etwas mitbringen, wenn Ihr auf Euren Abenteuerreisen darüber stolpern solltet?", sourceObjective = "Beschafft 10 Einheiten Helkalmarentinte.", progress = "Ich bin fast fertig mit diesen Pantoffeln.", completion = "Fantastisch!", sourceObjectiveStatus = "unverified-source-field" }
quests[38959] = { id = 38959, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurückgelassen", description = "Ich würde Euch liebend gern ein paar Tipps für die Schneiderei geben, doch ohne meine Muster und Vorräte kann ich Euch nur das Wenige beibringen, an das ich mich erinnern kann.\n\nWenn mein Gedächtnis mich nicht trügt, fehlt Euch nur noch ein gutes Muster für Handschuhe und eins für eine Kapuze.\n\nZuerst müsst Ihr an den Ort gehen, an dem Ihr mich das erste Mal getroffen habt, und Euch ein paar Dinge schnappen. Ich brauche Folgendes...", sourceObjective = "Sucht Lyndras' Zickzackschere, seinen Kasten mit Messwerkzeugen und seine Nähnadeln an dem Ort in Azsuna, an dem Ihr Lyndras das erste Mal angetroffen habt.", progress = "Ich hatte ja keine Ahnung, dass ich magisch hierherteleportiert werden würde, sonst hätte ich meine Sachen selbst zusammengesucht.", completion = "Ausgezeichnet! Es ist immer gut, mit gewohnten Werkzeugen zu hantieren.\n\nDamit wird es mir deutlich leichter fallen, Euch etwas zu zeigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[38960] = { id = 38960, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gut gefüttert", description = "Da Ihr Euch nach Azsuna begebt, könnt Ihr ja auch gleich etwas Futterstoff für unsere Projekte sammeln.\n\nDie Bären von Azsuna sind für ihr weiches und dennoch haltbares Fell bekannt.\n\nJagt sie in den Wäldern von Llothien und bringt mir ihre Felle.", sourceObjective = "Sammelt 15 Bärenfelle.", progress = "Haltet sie nicht für leichte Beute. Sie sind gerissen und brutal.", completion = "Das reicht allemal.", sourceObjectiveStatus = "unverified-source-field" }
quests[38961] = { id = 38961, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Auge Azsharas: Der verkommene Nachtsüchtige", description = "Um die Handschuhe zu fertigen, brauchen wir einen besonderen Gegenstand. Es wird nicht leicht sein, ihn zu beschaffen, {name}.\n\nDie Naga von Azsuna arbeiten angeblich darauf hin, eine schreckliche Kreatur in diese Welt zu beschwören.\n\nDas Herz der Kreatur beinhaltet enorme Energie, die wir in die Handschuhe kanalisieren könnten, um sie unheimlich mächtig zu machen.\n\nIch brauche... ich meine, wir brauchen das Herz, wenn wir ein geeignetes Paar Handschuhe für jemanden von Eurem Format fertigen wollen.", sourceObjective = "Besiegt Azsharas Zorn im Auge Azsharas und beschafft das Herz des Sturms.", progress = "Was habt Ihr gefunden?", completion = "Lyndras ist wieder fortgelaufen, bevor Ihr zurückgekehrt seid, {name}. Er hat eine Notiz und ein Muster für Euch hinterlassen.\n\nAuf der Notiz steht:\n\n\"Es tut mir leid, {name}, aber ich befürchte, dass ich eine Bedrohung für die anderen Schneider dieses Ladens darstellen könnte. Ich werde einen Ort suchen, an dem ich meine Begierde unter Kontrolle bringen oder der Verderbtheit erliegen werde. Es war mir eine Ehre, Euch zu unterrichten.\n\nHochachtungsvoll\n\nLyndras\"\n\nWie traurig...", sourceObjectiveStatus = "unverified-source-field" }
quests[38962] = { id = 38962, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg nach Suramar", description = "Ich kann mich erinnern, dass Lyndras etwas von einer Schneidergilde in Suramar erzählt hat. Vielleicht können ihre Mitglieder Euch dabei unterstützen, die Verarbeitung dieses neuen Stoffes zu ergründen.\n\nLeider habe ich gehört, dass sie sich auf die Seite der Dämonen geschlagen haben und dass jeder, der sich gegen sie stellt, auf der Stelle getötet wird.\n\nWenn Ihr Eure Nachforschungen fortsetzen wollt, müsst Ihr einen Weg finden, Euch sicher in ihrer Stadt zu bewegen.", sourceObjective = "Helft den Nachtsüchtigen von Suramar, bis Ihr einen Weg findet, wie Ihr Euch sicher unter den Elfen Suramars bewegen könnt.", completion = "Jetzt, da Ihr Euch überall in der Stadt frei bewegen könnt, wird es Zeit, nach neuen Meistern zu suchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[38963] = { id = 38963, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die abschließende Lektion?", description = "Lasst uns nun, da wir alles haben, was wir brauchen, an der Kapuze arbeiten.\n\nWenn wir fertig sind, werden wir mit den Handschuhen weitermachen.", sourceObjective = "Stellt eine handgefertigte seidengewebte Kapuze auf Tanithrias Sticktischchen her. Die dazu erforderlichen Materialien findet Ihr in ihrem Laden.", progress = "Kommt, {name}. Lasst uns etwas nähen.", completion = "Gut gemacht, {name}. Schon bald werdet Ihr derjenige sein, der mir etwas beibringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[38964] = { id = 38964, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo ist Lyndras jetzt schon wieder hin?", description = "Lyndras wird sich nicht weit entfernt haben können. Schließlich befinden wir uns Hunderte von Metern über dem Meer.\n\nIch habe heute Morgen einen Tumult im Alchemieladen auf der anderen Straßenseite vernommen. Ich hoffe, das war nicht Lyndras.\n\nKönntet Ihr bitte hinübergehen und Euch vergewissern?", sourceObjective = "Geht zum Alchemieladen auf der anderen Straßenseite.", sourceObjectiveStatus = "unverified-source-field" }
quests[38965] = { id = 38965, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturm auf die Violette Festung: In die Festung", description = "Jetzt, wo Lyndras in der Violetten Festung eingesperrt ist, fühlt Ihr Euch verantwortlich für ihn und wollt die Wahrheit hinter seinen Handlungen erfahren.\n\nVielleicht könnt Ihr ja mit ihm sprechen und einen Weg finden, wie er aus der Haft entlassen und wieder Eurer Obhut unterstellt werden kann.\n\nBegebt Euch zur Violetten Festung und findet heraus, was Lyndras zugestoßen ist.", sourceObjective = "Begebt Euch zur Violetten Festung und findet heraus, was Lyndras zugestoßen ist.", progress = "Habt Ihr herausgefunden, was Lyndras zugestoßen ist?", completion = "<Tanithria hört sich Euren Bericht über Lyndras' Schicksal an.>\n\nVerstehe... Das ist sehr bedauerlich.\n\nIch hatte mich gerade an ihn gewöhnt. Bitte entschuldigt mich, ich möchte einen Augenblick an ihn denken.", sourceObjectiveStatus = "unverified-source-field" }
quests[38966] = { id = 38966, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheime Seidenwebermethoden", description = "So, genug getrauert! Sehen wir uns jetzt mal seine Sachen an.\n\n<Tanithria blättert einen Augenblick lang durch Lyndras' Tagebuch. Ihre Augen weiten sich.>\n\nUnser Freund hatte Geheimnisse vor uns. Schaut Euch das an! Jedes einzelne Muster, das er uns gezeigt hat, kann noch weiter verbessert werden.\n\nFangen wir mit etwas Einfachem an, zum Beispiel den Armschienen. Die meisten Materialien habe ich hier, aber wegen des Schwefelpulvers werdet Ihr bei Alard Schmied in der Schmiede nachfragen müssen.", sourceObjective = "Stellt ein Paar meisterliche seidengewebte Armschienen her.\n\nDie dazu erforderlichen Materialien findet Ihr in der Schneiderei und in der Schmiede von Dalaran.", progress = "Diese Muster sind faszinierend. Ich hätte nie gedacht, dass man solche Ergebnisse mit einfacher Seide erzielen könnte.", completion = "Das Gute ist, dass wir jetzt ein paar effizientere seidengewebte Muster herstellen können.\n\nLeider können wir nun aber nichts mehr von Lyndras lernen. Was machen wir also als Nächstes?", sourceObjectiveStatus = "unverified-source-field" }
quests[38967] = { id = 38967, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kontakt zu den Nachtgeborenen", description = "Da Ihr Euch jetzt verkleiden könnt, solltet Ihr nach Suramar gehen und Euch auf die Suche nach dieser Schneidergilde machen.\n\nViel Glück, {name}. Und lasst Euch nicht erwischen.", sourceObjective = "Sprecht mit Leyweber Tytallo in Suramar.", completion = "Ah, ein Schneiderkollege. Ich freue mich, Eure Bekanntschaft zu machen, äh... {name}, habt Ihr gesagt?\n\nIch vermute, Ihr wollt unserer Gilde beitreten? Wo wurdet Ihr denn zuvor ausgebildet?", sourceObjectiveStatus = "unverified-source-field" }
quests[38968] = { id = 38968, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loyalitätsbeweis", description = "<Tytallo hört sich Euren Bericht über Lyndras an.>\n\nVerstehe. Aber Ihr scheint ja fast... Mitleid mit diesem Widerling zu haben.\n\nDie Nachtsüchtigen sind Lügner und Diebe. Und zwar ALLE, Lyndras eingeschlossen.\n\nIch dulde keine Schüler, die Respekt oder Mitleid für diese... Dinger haben. Habt Ihr mitbekommen, in was sie sich verwandeln, wenn sie in die Tiefen ihrer Verderbtheit sinken?\n\nWenn Ihr meine Gunst erlangen wollt, dann kommt erst wieder zu mir zurück, wenn das Blut der Verdorrten an Euch klebt.", sourceObjective = "Tötet 25 Verdorrte in Suramar.", completion = "Hmm.\n\nAlso gut. Fahren wir fort.", sourceObjectiveStatus = "unverified-source-field" }
quests[38969] = { id = 38969, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meisterliche Seidenweberei", description = "Während Tytallo sich mit der Ausrottung der Verdorrten befasst, übernehme ich die schlichteren Aspekte Eurer Ausbildung.\n\nWir müssen herausfinden, über wie viel Talent Ihr verfügt.\n\nStellt einen kompletten Satz seidengewebter Rüstung für mich her. Leyweber Mithrogane kann Euch für eine angemessene Präsentation einen Rüstungsständer zur Verfügung stellen.", sourceObjective = "Erwerbt einen Shal'doreirüstungsständer von Leyweber Mithrogane, fertigt einen kompletten Satz seidengewebter Rüstung an und stellt sie auf dem Rüstungsständer zur Schau.", progress = "Wenn Ihr von uns lernen wollt, braucht Ihr ein solides Grundwissen.", completion = "Eure Näharbeiten sind noch etwas grob, aber Ihr beherrscht bereits alle Grundlagen.\n\nGut gemacht.\n\nDas sage ich nicht allzu oft, also genießt es.", sourceObjectiveStatus = "unverified-source-field" }
quests[38970] = { id = 38970, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Webstuhl der anmutigen Königin", description = "Große Macht wird nur durch Opfer erlangt. Selbst die besten Schneider stoßen bei der Seidenweberei an ihre Grenzen. Um die Muster noch weiter zu verbessern, müssen wir besondere Wege gehen.\n\n{name}, Ihr seid jetzt so weit, den Umgang mit machtgetränktem Seidengewebe zu erlernen.\n\nVerwendet den Teleportationskristall hinter mir und sprecht mit Azayna, der Anführerin unseres Ordens.", sourceObjective = "Verwendet den Teleportationskristall in der Halle der Leyweber und sprecht dann mit Leyweberin Azayna.", completion = "Seht uns nicht so an, {name}. Unsere Dienstleistungen den Dämonen feilzubieten mag vielleicht moralisch fragwürdig sein, aber seit Azayna dieses Abkommen geschlossen hat, haben sich unsere Fertigkeiten enorm verbessert.\n\nIhr könnt Eure Ausbildung hier fortsetzen oder nicht. Wenn Ihr gehen wollt, wird Euch niemand aufhalten. Aber wenn Ihr etwas lernen wollt, dann sind wir weit und breit die Einzigen, die Euch weiterbringen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[38971] = { id = 38971, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exotische Textilien", description = "Dass ich hier bin, könnte mich mein Leben und meine Karriere kosten, <Schneider/Schneiderin>.\n\nIch habe mich schon immer für dämonische Stoffe interessiert, aber auf legale Weise kann ich nicht an sie herankommen.\n\nIch muss diese Stoffe einfach mit eigenen Augen sehen.\n\nIch möchte Azaynas Pakt mit den Dämonen nicht gefährden, aber Ihr... Ihr könntet die Dämonen angreifen, ohne die Aufmerksamkeit auf unsere Gilde zu lenken.\n\nIch interessiere mich besonders für die Robe eines bestimmten Dämons. Wenn Ihr mir davon einen Fetzen bringt, werde ich Euch beibringen, was ich weiß.", sourceObjective = "Beschafft den Schleier der Teufelsinschriften.", progress = "Ist wahrscheinlich auch besser, wenn Ihr mit diesem Ding kämpft. Ich weiß überhaupt nicht mit Waffen umzugehen.", completion = "Ausgezeichnete Arbeit. Ich werde mich gleich mit diesem Stoff beschäftigen. Und wie versprochen werde ich Euch lehren, was ich weiß. Seid Ihr mit unseren Mustern für Handschuhe vertraut?", sourceObjectiveStatus = "unverified-source-field" }
quests[38974] = { id = 38974, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hallen der Tapferkeit: Die richtige Frage", description = "Man könnte sich fragen, warum ein Leyweber über dem Leichnam eines Vrykul steht. Doch solche Fragen führen nur zu Ärger.\n\nFragen wir uns lieber, was man von den Verstorbenen lernen kann. Solch eine Frage fördert den Fortschritt.\n\nIch schätze, Ihr seid hier, um von mir zu lernen. Das Muster für Hosen aus machtgetränktem Seidengewebe, nicht wahr?\n\nWenn das stimmt, dann brauche ich etwas von jemandem, der von uns gegangen ist. In den Hallen der Tapferkeit haust der große Wächter Hymdall.\n\nBringt mir seinen Lendenschurz, dann bringe ich Euch das Muster bei.", sourceObjective = "Besiegt Hymdall in den Hallen der Tapferkeit und erlangt seinen Lendenschurz.", progress = "Die richtigen Fragen zu stellen, kann Euch weit bringen.", completion = "<Tellumi nimmt Euch den Lendenschurz ab und grinst Euch verschmitzt an.>\n\nIch glaube, Ihr habt jetzt verstanden, dass Ihr viel mehr lernt, wenn Ihr eine Situation aus einer funktionellen und nicht aus einer rückständigen Warte betrachtet.", sourceObjectiveStatus = "unverified-source-field" }
quests[38975] = { id = 38975, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inspiriert mich!", description = "Ich werde nie aufhören, mich für Roben und Gewänder zu interessieren. Handschuhe, Gürtel und Umhänge sind mir egal. Es gibt einfach nichts Besseres als eine gute Robe.\n\nIch werde Euch das Muster für eine machtgetränkte seidengewebte Robe überlassen, wenn Ihr mir ein paar Muster für Roben und Gewänder zeigt, die Ihr auf Euren Reisen gelernt habt.", sourceObjective = "Stellt im Beisein von Leyweber Mithrogane eine braune Leinenrobe, ein weißes Wollkleid, ein einfaches schwarzes Kleid, eine frostgewirkte Robe und eine Geistheilerrobe her.\n\nWenn Ihr ein Muster nicht kennt, könnt Ihr es bei den Schneiderlehrern in den Hauptstädten erlernen.", completion = "Nicht ganz, was ich erwartet habe, aber zumindest eine interessante Geschichtsstunde. Ihr könnt die Roben behalten. Ich habe alles, was ich brauche, beim Zusehen gelernt.\n\nUnd wie versprochen zeige ich Euch jetzt, was ich weiß.", sourceObjectiveStatus = "unverified-source-field" }
