quests[38989] = { id = 38989, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie lauten Eure Befehle, General?", description = "<General/Generalin>, Eure Truppen im Tanaandschungel warten auf Eure Befehle. Begebt Euch zur taktischen Karte dort, um diese Befehle zu erteilen.\n\nFür die Horde!", sourceObjective = "Begebt Euch zur taktischen Karte von Tanaan im Tanaandschungel.", completion = "Lok'tar, Generalin. Eure Truppen warten auf Eure Befehle.", sourceObjectiveStatus = "unverified-source-field" }
quests[38990] = { id = 38990, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf der Eiskronenzitadelle", description = "<Eine mächtige Präsenz dringt erneut in Eure Gedanken.>\n\nIch habe Eure Brüder und Schwestern zur Eiskrone gerufen, damit sie sich auf den kommenden Konflikt vorbereiten, doch für Euch habe ich ein wichtigeres Schicksal auserwählt. Ihr, {name}, werdet <der Überbringer/die Überbringerin> unserer Rache sein!\n\nBenutzt das Schwarze Tor, um nach Acherus zurückzukehren, dann werde ich Euch Eure Aufgabe offenbaren.", sourceObjective = "Verwendet Eure Fähigkeit 'Schwarzes Tor', um nach Eiskrone zu gelangen, und beschafft die Klingen des gefallenen Prinzen.", completion = "Es war eine weise Entscheidung des Lichkönigs, Euch diese Klingen zu überlassen, {name}. Ihr habt wieder und wieder bewiesen, dass Ihr ihrer würdig seid.\n\nDoch ich muss gestehen, ich bin ganz froh, dass sie nicht an mich gingen. Ich habe genug von magischen Waffen, die mein Schicksal kontrollieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[38993] = { id = 38993, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "First Mission Sent" }
quests[38994] = { id = 38994, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "TRACKING Encounter Botanist" }
quests[38996] = { id = 38996, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie lauten Eure Befehle, General?", description = "Exarchin Yrel meldet aus der Löwenwacht im Tanaandschungel, dass Eure Truppen neue Befehle erwarten.\n\nFür die Allianz!", sourceObjective = "Sprecht mit Yrel in der Löwenwacht im Tanaandschungel.", completion = "Seid gegrüßt, General. Eure Truppen warten auf Eure Befehle am Kartentisch.", sourceObjectiveStatus = "unverified-source-field" }
quests[39000] = { id = 39000, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir brauchen keinen Bibliotheksausweis", description = "Wenn sich aus der Geschichte irgendwas lernen lässt, dann bildet Gul'dan eine ganze Generation Hexenmeister für den Kampf gegen uns aus. Wir müssen schnell handeln, wenn wir Schlimmeres verhindern und dieser Gefahr zuvorkommen wollen.\n\nBegebt Euch mit Euren Heldengefährten in die Tiefen der Höllenfeuerzitadelle und nehmt Gul'dans Handlangern die Folianten des Chaos ab.\n\nIhr dürft sie nicht lesen, denn sie sind gefährlich. Und auch nicht die Bilder betrachten.\n\n<Khadgar erschaudert.>\n\nAUF KEINEN FALL die Bilder betrachten.", sourceObjective = "Sammelt 33 Folianten des Chaos von den Bossen in der Höllenfeuerzitadelle ein.", progress = "Was ist mit diesen Büchern, {name}?", completion = "<Khadgar schaut sich zunehmend angewidert die Rücken der Bücher an, die Ihr ihm aushändigt.>\n\nVersteht Ihr jetzt? Das ist wie eine Enzyklopädie für Psychopathen.", sourceObjectiveStatus = "unverified-source-field" }
quests[39001] = { id = 39001, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Farahlon, ahoi!", description = "{name}, habt Ihr schon mal von Farahlon gehört? Erzmagier Vargoth hört nicht auf, darüber zu reden – die wunderschönen Felder und Wälder sind mit natürlichen Kristallformationen bedeckt, die es zum magischen Nexus von Draenor machen. Es ist praktisch unerreichbar. Die magischen Stürme im umgebenden Meer sind häufig und unberechenbar.\n\nFür Euren Ring brauchen wir ein magisches Artefakt aus Farahlon. Ihr werdet eine erstklassige Mannschaft brauchen, um lebendig dorthin und zurückzugelangen. Wählt sie sorgfältig aus und bringt mir das Artefakt!", sourceObjective = "Benutzt Eure Werft, um die Marinemission \"Auf nach Farahlon!\" abzuschließen und die Farahlonperle zu beschaffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[39002] = { id = 39002, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oger aus der Tiefe", description = "Das hättet Ihr vielleicht nicht erwartet, aber zur Blütezeit des gorianischen Ogerreichs hatten sie eine kleine, aber mächtige Flotte. Dabei wird Euch nicht überraschen, dass viele ihrer größten Kriegsschiffe sanken. Schließlich wurden sie aus Stein gemeißelt.\n\nIch habe eine alte Karte gefunden, die den letzten bekannten Standort der \"Fuß des Kaisers\" zeigt, die mit einem wertvollen Artefakt im Meer verschollen ist. Ein Ogerdekodierer, den ich gut gebrauchen könnte.\n\nAlso! Um ihn zu beschaffen, braucht Ihr ein U-Boot und eine erstklassige Crew. Ich überlasse Euch eine äußerst gefährliche Aufgabe.", sourceObjective = "Benutzt Eure Werft, um die Marinemission \"Oger aus der Tiefe\" abzuschließen und den durchnässten Ogerdekodierer zu beschaffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[39003] = { id = 39003, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bücher gut durch", description = "{name}, wir müssen diese Folianten vernichten. Gequälte Seelen sind auf vielen Seiten gebunden, also dürfen wir sie nicht einfach verbrennen. Cordana wird wissen, was zu tun ist.\n\nBringt diese Bücher zu meinem Turm in Zangarra und übergebt sie Cordana. Lasst es mich wissen, wenn die Tat vollbracht ist.", sourceObjective = "Bringt Gul'dans Bücher des Chaos zu Cordana in Zangarra und stellt sicher, dass sie vernichtet werden.", completion = "<Khadgar ist erschüttert, als Ihr von Eurer Begegnung am Turm erzählt.>\n\nCordana...? Oh, nicht doch, nicht doch... Sie schien in letzter Zeit etwas zurückgezogen. Ich dachte... ich dachte, sie wollte nur als eiskalte Wächterin angesehen werden. Ich wusste ja nicht...\n\nJa, {name}! Versteht Ihr jetzt? Genau so geht Gul'dan vor. Er findet unsere Schwächen und nutzt sie gegen uns. Seid vorsichtig, wem Ihr Vertrauen schenkt. Ach, Cordana!\n\n\n\nCordana.", sourceObjectiveStatus = "unverified-source-field" }
quests[39004] = { id = 39004, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inkarnation der Dunkelheit", description = "Uns steht noch eine letzte Aufgabe bevor, {name}. Wir müssen Gul'dan besiegen und seine Pläne für diese Welt zunichtemachen.\n\nIch kann Euch keine Belohnung bieten – ich habe Euch schon alles gegeben, was in meiner Macht steht.\n\nKommt. Wenn Ihr mit Euren Verbündeten bereit seid, marschieren wir gegen die Höllenfeuerzitadelle... und setzen dem ein Ende.", sourceObjective = "Jagt Gul'dan und bekämpft ihn in der Höllenfeuerzitadelle.", completion = "<Khadgars Gesicht ist aschfahl.>\n\nDraenor ist gerettet, {name}. Aber die Legion ist viel mächtiger, als selbst ich ahnte. Und Gul'dan, diese Schlange, ist immer noch am Leben. Wo immer er steckt.\n\nBleibt hier und feiert mit den anderen, {name}. Ihr habt es Euch verdient. Ich aber werde nach Azeroth zurückkehren und mich um diese Sache kümmern. Und ich hoffe, dass Ihr mich dort aufsucht, wenn die Zeit reif ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[39005] = { id = 39005, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Second Mission Sent" }
quests[39006] = { id = 39006, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Second Mission Complete" }
