quests[39011] = { id = 39011, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rabenwehrinvasion", description = "Dies war einst eine friedliche und wohlhabende Gegend. Aber dann sahen wir die ersten schlechten Vorzeichen: seltsame Erkrankungen, verdorbene Ernten und solche Dinge. Und jetzt greifen uns die Geister vom Schloss auf der anderen Seite des Flusses an, und untote Attentäter ermorden unsere Fischer, sodass wir nichts mehr zu essen haben.\n\nWir sind die letzte Familie, die so nah am Schloss lebt, aber wir wagen es nicht, fortzugehen: Dieser Fluss ist der beste Weg, um die gefangenen Fische in die Stadt zu bringen. Bitte, könnt Ihr uns nicht helfen, diese Untoten zu bekämpfen?", sourceObjective = "Tötet 7 Attentäter der Rabenwehr in Bradenbach.", sourceObjectiveStatus = "unverified-source-field" }
